head.b:skin:
:root {
  --bg: #080910; --surface: #111320; --surface-2: #171a2a;
  --text: #f7f7fb; --muted: #9b9eb2; --line: rgba(255,255,255,.09);
  --purple: #9b5cff; --pink: #ff4f91; --radius: 18px;
  --content: 1240px;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; background: var(--bg); }
body {
  margin: 0; background: var(--bg); color: var(--text);
  font: 15px/1.55 Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}
a { color: inherit; text-decoration: none; }
button, input { font: inherit; }
button { cursor: pointer; }
img { max-width: 100%; display: block; }
.site-shell { min-height: 100vh; overflow: hidden; }
.topbar {
  position: sticky; top: 0; z-index: 50; backdrop-filter: blur(18px);
  background: rgba(8,9,16,.86); border-bottom: 1px solid var(--line);
}
.nav {
  width: min(var(--content), calc(100% - 40px)); min-height: 72px; margin: auto;
  display: flex; align-items: center; gap: 28px;
}
.brand { display:flex; align-items:center; gap:10px; font-weight:850; letter-spacing:-.7px; font-size:22px; }
.brand-mark {
  width:34px; height:34px; display:grid; place-items:center; border-radius:11px;
  background:linear-gradient(135deg,var(--purple),var(--pink)); color:white;
  box-shadow:0 7px 26px rgba(155,92,255,.28); font-weight:900;
}
.nav-links { display:flex; align-items:center; gap:24px; color:#c6c7d3; font-size:14px; }
.nav-links a:hover, .nav-links a.active { color:white; }
.nav-spacer { flex:1; }
.search-box {
  width:220px; display:flex; align-items:center; gap:9px; padding:10px 13px;
  background:#141624; border:1px solid var(--line); border-radius:12px; color:var(--muted);
}
.search-box input { width:100%; min-width:0; border:0; outline:0; color:white; background:transparent; }
.nav-action {
  border:1px solid rgba(178,133,255,.35); color:#fff; border-radius:12px;
  padding:10px 15px; background:rgba(155,92,255,.13); font-weight:700;
}
.mobile-menu { display:none; border:1px solid var(--line); color:white; background:var(--surface); border-radius:11px; padding:9px 12px; }
.container { width:min(var(--content),calc(100% - 40px)); margin:0 auto; }
.hero { padding:42px 0 26px; }
.hero-panel { min-height:390px; border:1px solid var(--line); border-radius:26px; overflow:hidden; position:relative; isolation:isolate; background:linear-gradient(135deg,#242039,#111321 55%,#311b39); }
.featured-track { position:relative; min-height:390px; }
.featured-slide { display:none; min-height:390px; align-items:flex-end; position:relative; isolation:isolate; overflow:hidden; }
.featured-slide:first-child { display:flex; }
.featured-slide.is-active { display:flex; }
.featured-backdrop { position:absolute; inset:0; z-index:-2; width:100%; height:100%; object-fit:cover; opacity:.72; }
.featured-slide:before { content:""; position:absolute; inset:0; z-index:-1; background:linear-gradient(90deg,rgba(7,8,15,.98) 0%,rgba(7,8,15,.82) 42%,rgba(7,8,15,.2) 100%),linear-gradient(0deg,rgba(8,9,16,.72),transparent 65%); }
.hero-content { max-width:650px; padding:clamp(24px,5vw,48px); }
.eyebrow { color:#c49aff; text-transform:uppercase; letter-spacing:2px; font-size:11px; font-weight:800; }
.hero h1 { font-size:clamp(34px,5vw,60px); line-height:1.02; letter-spacing:-2px; margin:14px 0; max-width:620px; }
.hero p { color:#d0cedb; max-width:490px; margin:0 0 24px; }
.featured-controls { position:absolute; right:22px; bottom:22px; z-index:3; display:flex; align-items:center; gap:8px; }
.featured-arrow { width:40px; height:40px; border:1px solid rgba(255,255,255,.25); border-radius:50%; color:#fff; background:rgba(10,10,18,.62); cursor:pointer; }
.featured-arrow:hover,.featured-arrow:focus-visible { background:var(--purple); outline:2px solid rgba(255,255,255,.7); outline-offset:2px; }
.featured-dots { display:flex; gap:6px; align-items:center; margin:0 5px; }
.featured-dot { width:7px; height:7px; padding:0; border:0; border-radius:50%; background:rgba(255,255,255,.42); cursor:pointer; }
.featured-dot[aria-current='true'] { width:22px; border-radius:8px; background:#c49aff; }
@media (prefers-reduced-motion:no-preference) { .featured-slide.is-active { animation:dramoraSlideIn .35s ease both; } }
@keyframes dramoraSlideIn { from { opacity:.55; } to { opacity:1; } }
.button-primary {
  display:inline-flex; align-items:center; justify-content:center; gap:9px;
  padding:12px 19px; border:0; border-radius:12px; color:white; font-weight:800;
  background:linear-gradient(110deg,var(--purple),#7655ed 55%,var(--pink));
  box-shadow:0 10px 28px rgba(155,92,255,.22);
}
.button-ghost { display:inline-flex; padding:11px 17px; border:1px solid var(--line); border-radius:12px; margin-left:8px; background:rgba(255,255,255,.06); }
.section { padding:20px 0 42px; }
.section-head { display:flex; align-items:end; justify-content:space-between; gap:16px; margin-bottom:18px; }
.section-head h2 { margin:0; font-size:23px; letter-spacing:-.6px; }
.section-head p { margin:4px 0 0; color:var(--muted); font-size:13px; }
.text-link { color:#c49aff; font-weight:700; font-size:13px; }
.chips { display:flex; flex-wrap:wrap; gap:9px; margin:0 0 22px; }
.chip { padding:8px 13px; border:1px solid var(--line); border-radius:999px; color:#c8c8d4; background:var(--surface); font-size:12px; }
.chip.active { color:white; border-color:rgba(155,92,255,.5); background:rgba(155,92,255,.15); }
.drama-grid { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:18px; }
.drama-card { min-width:0; }
.poster {
  aspect-ratio: 3/4; position:relative; overflow:hidden; border-radius:15px;
  background:linear-gradient(145deg,#2d2542,#171827 55%,#4a2441);
  border:1px solid var(--line);
}
.poster img { width:100%; height:100%; object-fit:cover; transition:transform .35s ease; }
.drama-card:hover .poster img { transform:scale(1.045); }
.poster-placeholder { position:absolute; inset:0; display:grid; place-items:center; color:rgba(255,255,255,.65); font-size:12px; text-align:center; padding:15px; }
.poster-shade { position:absolute; inset:40% 0 0; background:linear-gradient(transparent,rgba(0,0,0,.55)); pointer-events:none; }
.drama-meta { padding:11px 2px 0; }
.drama-meta h3 { font-size:14px; line-height:1.35; margin:0 0 5px; font-weight:750; }
.drama-meta p { color:var(--muted); font-size:12px; margin:0; }
.label-row { display:flex; gap:6px; margin-top:8px; flex-wrap:wrap; }
.mini-label { color:#d9c5ff; background:rgba(155,92,255,.13); border-radius:6px; padding:3px 7px; font-size:10px; }
.content-layout { display:grid; grid-template-columns:minmax(0,1fr) 280px; gap:28px; padding-bottom:60px; }
.main-posts { min-width:0; }
.blog-content-container { padding-top:0; }
.blog-content-layout { grid-template-columns:minmax(0,1fr); }
.blog-content-section .widget.Blog:empty { display:none; }
.post-card { background:var(--surface); border:1px solid var(--line); border-radius:var(--radius); padding:22px; margin-bottom:16px; }
.post-card h2 { margin:0 0 10px; font-size:23px; }
.post-card .post-body { color:#c6c7d3; }
.post-body img { border-radius:12px; }
.sidebar-box { padding:18px; border:1px solid var(--line); border-radius:var(--radius); background:var(--surface); margin-bottom:16px; }
.sidebar-box h3 { margin:0 0 12px; font-size:15px; }
.sidebar-box p { color:var(--muted); font-size:13px; margin:0; }
.site-footer { border-top:1px solid var(--line); padding:28px 0; color:var(--muted); font-size:12px; }
.footer-inner { display:flex; justify-content:space-between; gap:20px; flex-wrap:wrap; }
.empty-state { padding:35px; text-align:center; color:var(--muted); border:1px dashed var(--line); border-radius:16px; }
.continue-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(190px,1fr)); gap:15px; }
.continue-card { min-width:0; overflow:hidden; border:1px solid var(--line); border-radius:15px; background:var(--surface); }
.continue-card-link { display:block; color:inherit; }
.continue-poster { position:relative; aspect-ratio:16/9; overflow:hidden; background:linear-gradient(135deg,#302344,#171827); }
.continue-poster img { width:100%; height:100%; object-fit:cover; }
.continue-poster-fallback { display:grid; width:100%; height:100%; place-items:center; color:#d9c5ff; font-weight:850; letter-spacing:2px; }
.continue-copy { padding:11px 12px 13px; }
.continue-copy strong { display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:13px; }
.continue-copy span { display:block; margin-top:5px; color:var(--muted); font-size:11px; }
.continue-progress { height:4px; margin-top:10px; overflow:hidden; border-radius:9px; background:rgba(255,255,255,.12); }
.continue-progress span { display:block; height:100%; border-radius:9px; background:linear-gradient(90deg,var(--purple),var(--pink)); }
.feed-section { content-visibility:auto; contain-intrinsic-size:460px; }
.feed-section .drama-card { min-width:0; }
.feed-section .drama-card a { display:block; height:100%; }
.feed-section .drama-meta p { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.post-actions { display:flex; flex-wrap:wrap; gap:10px; margin:0 0 18px; }
.favorite-action,.share-post-action { border:1px solid rgba(178,133,255,.35); color:#fff; background:rgba(155,92,255,.12); border-radius:11px; padding:10px 14px; font-weight:700; }
.favorite-action.is-saved { background:rgba(255,79,145,.16); border-color:rgba(255,79,145,.4); }
.registered-player-note { color:#d8c3ff; font-size:12px; margin:8px 0; }
@media(max-width:640px) {
  .continue-grid { grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; }
  .feed-section .drama-grid { grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; }
  .hero { padding-top:22px; }
  .hero-panel,.featured-track,.featured-slide { min-height:330px; }
  .featured-controls { right:12px; bottom:12px; }
}
@media(prefers-reduced-motion:reduce) {
  html { scroll-behavior:auto; }
  *,*::before,*::after { animation-duration:.01ms !important; transition-duration:.01ms !important; }
}



/* Blogger post and episode presentation */
.blog-posts { margin:0; }
.date-outer { margin:0 0 18px; }
.post-outer { margin:0 0 18px; }
.post { background:var(--surface); border:1px solid var(--line); border-radius:var(--radius); padding:clamp(18px,3vw,30px); overflow:hidden; }
.post-title, .post-title.entry-title { color:var(--text); font-size:clamp(24px,3vw,36px); line-height:1.15; letter-spacing:-.8px; margin:0 0 12px; }
.post-title a { color:inherit; }
.post-header, .post-header-line-1, .post-footer { color:var(--muted); font-size:12px; }
.post-body { color:#d0d1dc; font-size:15px; line-height:1.8; overflow-wrap:anywhere; }
.post-body h2,.post-body h3 { color:white; line-height:1.25; margin:26px 0 12px; }
.post-body p { margin:0 0 16px; }
.post-body a { color:#c49aff; text-decoration:underline; text-underline-offset:3px; }
.post-body img { height:auto; max-width:100%; border-radius:13px; margin:16px auto; }
.post-body iframe { max-width:100%; border:0; border-radius:14px; }
/* Blogger-native uploaded videos use an OBJECT element, not a VIDEO/IFRAME tag. */
.post-body object.BLOG_video_class, .post-body object[id^='BLOG_video-'] { display:block; width:100% !important; max-width:100%; height:auto; aspect-ratio:16/9; min-height:180px; max-height:78vh; margin:18px auto; background:#000; border:0; border-radius:16px; }
.post-body .dramora-thumbnail { display:none !important; }
.post-body .dramora-episode-poster { display:block; width:auto; max-width:min(100%,480px); height:auto; margin:16px auto; object-fit:contain; }
.post-body video { display:block; width:100%; max-height:78vh; background:#000; border-radius:16px; }
.drama-player, .episode-player, .video-container { width:100%; aspect-ratio:16/9; background:#000; border:1px solid var(--line); border-radius:17px; overflow:hidden; margin:20px 0 24px; }
.drama-player iframe, .episode-player iframe, .video-container iframe,
.drama-player video, .episode-player video, .video-container video { width:100%; height:100%; display:block; border:0; object-fit:contain; }
.post-body .separator { margin:18px auto; }
.post-body blockquote { margin:18px 0; padding:14px 18px; border-left:3px solid var(--purple); background:rgba(155,92,255,.08); border-radius:0 12px 12px 0; color:#d7d2e4; }
.post-labels a { display:inline-block; margin:5px 5px 0 0; padding:5px 9px; color:#d9c5ff; background:rgba(155,92,255,.13); border-radius:7px; font-size:11px; }
.blog-pager { display:flex; justify-content:space-between; gap:12px; margin:20px 0; }
.blog-pager a { padding:10px 14px; border:1px solid var(--line); background:var(--surface); border-radius:10px; color:#d9c5ff; }
.post-share-buttons, .post-icons, .feed-links { opacity:.85; }
.comments { margin-top:24px; padding-top:18px; border-top:1px solid var(--line); }
.comments h4 { color:white; }
.comment-thread, .comment-form { color:#c6c7d3; }
.status-msg-wrap { margin:20px 0; padding:16px; border:1px solid var(--line); border-radius:12px; color:var(--muted); }
/* DRAMORA V9.7 — one-post multi-episode hybrid series layout */
.dramora-hybrid-series { display:grid; gap:18px; }
.dramora-series-overview { display:grid; grid-template-columns:minmax(0,1fr); gap:18px; align-items:start; padding:16px; border:1px solid var(--line); border-radius:18px; background:linear-gradient(140deg,rgba(155,92,255,.12),rgba(255,255,255,.025)); }
.dramora-series-cover { display:none!important; }
.dramora-series-overview h2 { margin:0 0 8px; color:#fff; font-size:23px; line-height:1.2; }
.dramora-series-description { color:#c9c5d5; font-size:13px; line-height:1.75; white-space:pre-wrap; }
.dramora-hybrid-player { min-width:0; padding:14px; border:1px solid rgba(174,126,255,.22); border-radius:17px; background:#0b0c13; }
.dramora-hybrid-player h3 { margin:0 0 11px; color:#fff; font-size:16px; }
.dramora-hybrid-player .dramora-native-video { display:block; width:100%!important; max-width:100%; min-height:190px; height:auto; aspect-ratio:16/9; margin:0 auto; background:#000; border:0; border-radius:12px; }
.dramora-current-episode-description { margin:12px 2px 0; color:#bdb8cd; font-size:13px; line-height:1.65; white-space:pre-wrap; }
.dramora-episode-heading { margin:2px 0 0; color:#fff; font-size:18px; }
.dramora-hybrid-episode-list { display:grid; grid-template-columns:repeat(auto-fill,minmax(130px,1fr)); gap:10px; }
.dramora-hybrid-episode { display:flex; align-items:center; gap:10px; min-width:0; padding:12px; text-align:left; color:#e9e4f4; border:1px solid var(--line); border-radius:12px; background:var(--surface-2); cursor:pointer; }
.dramora-hybrid-episode:hover,.dramora-hybrid-episode.is-active { border-color:rgba(174,126,255,.7); background:rgba(155,92,255,.16); }
.dramora-hybrid-episode-number { flex:0 0 34px; width:34px; height:34px; display:grid; place-items:center; border-radius:10px; background:rgba(155,92,255,.2); color:#e4d4ff; font-size:11px; font-weight:850; }
.dramora-hybrid-episode-copy { min-width:0; display:grid; gap:3px; }
.dramora-hybrid-episode-copy strong { font-size:12px; overflow-wrap:anywhere; }
.dramora-hybrid-episode-copy small { color:var(--muted); font-size:10px; }
@media(max-width:560px) { .dramora-series-overview { grid-template-columns:minmax(0,1fr); gap:12px; padding:12px; } .dramora-series-overview h2 { font-size:18px; } .dramora-hybrid-episode-list { grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; } .dramora-hybrid-episode { padding:9px; } }
.post-body .episode-heading { margin:24px 0 10px; color:white; font-size:20px; font-weight:800; }
.post-body .episode-note { color:var(--muted); font-size:13px; }
.post-body .episode-list { display:grid; grid-template-columns:repeat(auto-fit,minmax(130px,1fr)); gap:10px; margin:18px 0; }
.post-body .episode-list a { display:block; padding:12px; border:1px solid var(--line); border-radius:11px; background:var(--surface-2); text-decoration:none; }
.post-body .episode-list a:hover { border-color:rgba(155,92,255,.55); background:rgba(155,92,255,.1); }
.post-body .watch-notice { padding:12px 14px; border:1px solid rgba(155,92,255,.25); background:rgba(155,92,255,.08); color:#d9c5ff; border-radius:11px; font-size:13px; }
.blog-feeds, .blog-mobile-link { display:none; }
@media(max-width:760px) {
  .post { padding:17px; border-radius:15px; }
  .post-body { font-size:14px; }
  .post-body iframe { width:100%; }
  .drama-player, .episode-player, .video-container { border-radius:12px; }
}


/* DRAMORA V3 — Firebase account and personal library */
[hidden] { display: none !important; }
body.modal-open { overflow: hidden; }
.auth-modal { display:none; position:fixed; inset:0; z-index:1000; place-items:center; padding:18px; }
.auth-modal.is-open { display:grid; }
.auth-backdrop { position:absolute; inset:0; background:rgba(2,3,9,.78); backdrop-filter:blur(10px); }
.auth-dialog { position:relative; z-index:1; width:min(100%,440px); max-height:min(92vh,760px); overflow:auto;
  padding:30px; border:1px solid rgba(190,150,255,.22); border-radius:24px;
  background:linear-gradient(160deg,#171526,#0e101b 65%); box-shadow:0 28px 100px rgba(0,0,0,.6); }
.auth-close { position:absolute; top:13px; right:14px; width:36px; height:36px; border:1px solid var(--line);
  border-radius:11px; background:rgba(255,255,255,.05); color:white; font-size:21px; }
.auth-brand { display:flex; align-items:center; gap:9px; color:#d7c2ff; font-size:12px; font-weight:850; letter-spacing:2px; }
.auth-brand-mark { display:grid; place-items:center; width:28px; height:28px; border-radius:9px;
  background:linear-gradient(135deg,var(--purple),var(--pink)); color:#fff; letter-spacing:0; }
.auth-dialog h2 { margin:19px 0 5px; font-size:28px; letter-spacing:-.8px; }
.auth-subtitle { margin:0 0 21px; color:var(--muted); font-size:13px; }
.auth-field { display:block; margin:13px 0; color:#d9d9e5; font-size:12px; font-weight:700; }
.auth-field input { display:block; width:100%; margin-top:7px; padding:13px 14px; border:1px solid var(--line);
  border-radius:11px; outline:none; background:#0a0c15; color:#fff; }
.auth-field input:focus { border-color:rgba(174,126,255,.7); box-shadow:0 0 0 3px rgba(155,92,255,.12); }
.auth-submit,.auth-google,.auth-secondary { width:100%; min-height:45px; border-radius:11px; font-weight:800; }
.auth-submit { margin-top:10px; border:0; color:white; background:linear-gradient(110deg,var(--purple),#7655ed 55%,var(--pink)); }
.auth-google,.auth-secondary { margin-top:10px; border:1px solid var(--line); color:#f4f1fb; background:rgba(255,255,255,.045); }
.auth-text-button { border:0; padding:8px 0; color:#c9aaff; background:transparent; font-size:12px; font-weight:700; }
.auth-switch { display:block; width:100%; margin-top:12px; text-align:center; }
.auth-message { padding:11px 12px; border-radius:10px; margin:12px 0; font-size:12px; line-height:1.5; }
.auth-message.error { border:1px solid rgba(255,100,130,.28); background:rgba(255,70,100,.09); color:#ffb9c6; }
.auth-message.success { border:1px solid rgba(100,220,170,.24); background:rgba(60,190,130,.09); color:#a9f0ce; }
.auth-verification { margin-top:16px; padding:14px; border:1px solid rgba(155,92,255,.28); border-radius:13px; background:rgba(155,92,255,.08); }
.auth-verification p,.auth-account-copy { color:var(--muted); font-size:12px; line-height:1.6; }
.auth-account-name { margin:18px 0 2px; font-size:19px; font-weight:800; }
.auth-account-email { margin:0 0 12px; color:var(--muted); font-size:12px; overflow-wrap:anywhere; }
.library-page { padding:8px 0 35px; }
.library-page-head { margin:0 0 22px; }
.library-page-head h1 { margin:0 0 6px; font-size:clamp(27px,4vw,38px); letter-spacing:-1px; }
.library-page-head p { margin:0; color:var(--muted); font-size:13px; }
.library-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:16px; }
.library-card { min-width:0; overflow:hidden; border:1px solid var(--line); border-radius:15px; background:var(--surface); }
.library-card-link { display:block; }
.library-card img,.library-card-placeholder { display:grid; width:100%; aspect-ratio:3/4; object-fit:cover; background:linear-gradient(145deg,#2d2542,#171827 55%,#4a2441); }
.library-card-placeholder { place-items:center; color:var(--muted); font-size:12px; }
.library-card-copy { padding:11px; }
.library-card-copy h3 { margin:0 0 8px; font-size:13px; line-height:1.4; }
.library-remove { border:1px solid var(--line); border-radius:9px; padding:7px 10px; color:#e7d8ff; background:rgba(155,92,255,.1); font-size:11px; }
.library-empty { padding:28px; border:1px dashed var(--line); border-radius:14px; color:var(--muted); text-align:center; }
.library-primary { display:inline-flex; align-items:center; justify-content:center; min-height:42px; padding:0 16px; border:0;
  border-radius:11px; color:white; background:linear-gradient(110deg,var(--purple),#7655ed 55%,var(--pink)); font-weight:800; }
.discover-tools { display:grid; gap:13px; margin:0 0 18px; }
.discover-search { width:100%; min-height:45px; padding:0 14px; border:1px solid var(--line); border-radius:12px; outline:none; color:#fff; background:#10121e; }
.discover-search:focus { border-color:rgba(174,126,255,.7); box-shadow:0 0 0 3px rgba(155,92,255,.1); }
.discover-chip-row { display:flex; flex-wrap:wrap; gap:8px; }
.discover-chip { padding:8px 12px; border:1px solid var(--line); border-radius:999px; color:#c9c9d6; background:var(--surface); font-size:11px; font-weight:750; }
.discover-chip.active { color:#fff; border-color:rgba(155,92,255,.5); background:rgba(155,92,255,.16); }
.discover-count { color:var(--muted); font-size:11px; }
.discover-summary { display:-webkit-box; -webkit-line-clamp:3; -webkit-box-orient:vertical; overflow:hidden; margin:7px 0 0; color:var(--muted); font-size:11px; line-height:1.55; }
.discover-card-labels { display:flex; flex-wrap:wrap; gap:5px; margin-top:8px; }
.discover-load-more { display:flex; justify-content:center; margin:22px 0 8px; }
.discover-load-more button { min-height:42px; padding:0 18px; border:1px solid rgba(174,126,255,.3); border-radius:11px; color:#e6d9ff; background:rgba(155,92,255,.1); font-size:12px; font-weight:800; }
.series-section { margin:28px 0 34px; }
.series-section h2 { margin:0 0 14px; color:#fff; font-size:20px; letter-spacing:-.02em; }
.series-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(210px,1fr)); gap:12px; }
.series-card { display:block; min-width:0; padding:16px; border:1px solid var(--line); border-radius:15px;
  background:linear-gradient(145deg,rgba(155,92,255,.11),rgba(255,255,255,.025)); text-decoration:none; }
.series-card:hover { border-color:rgba(174,126,255,.55); transform:translateY(-1px); }
.series-card strong { display:block; color:#fff; font-size:14px; overflow-wrap:anywhere; }
.series-card span { display:block; margin-top:7px; color:var(--muted); font-size:11px; }
.series-episode-list { display:grid; gap:10px; margin-top:18px; }
.series-episode { display:flex; align-items:center; justify-content:space-between; gap:14px; padding:14px;
  border:1px solid var(--line); border-radius:13px; background:var(--surface); text-decoration:none; }
.series-episode:hover { border-color:rgba(174,126,255,.5); background:rgba(155,92,255,.07); }
.series-episode-copy { min-width:0; }
.series-episode-copy strong { display:block; color:#fff; font-size:13px; overflow-wrap:anywhere; }
.series-episode-copy span { display:block; margin-top:5px; color:var(--muted); font-size:11px; }
.series-episode-number { flex:0 0 auto; min-width:42px; text-align:center; padding:8px 9px; border-radius:10px;
  color:#e9dcff; background:rgba(155,92,255,.15); font-size:11px; font-weight:850; }
.series-back { display:inline-flex; margin:0 0 16px; color:#d9c7ff; font-size:12px; text-decoration:none; }
@media(max-width:600px) { .series-grid { grid-template-columns:repeat(2,minmax(0,1fr)); gap:9px; }
  .series-card { padding:13px; } .series-episode { padding:12px; } }
.registered-player { margin:0 0 22px; padding:13px; border:1px solid rgba(174,126,255,.2); border-radius:17px; background:linear-gradient(145deg,rgba(155,92,255,.08),rgba(255,255,255,.02)); }
.registered-player h2 { margin:0 0 10px; color:#f5f0ff; font-size:16px; }
.registered-player video { display:block; width:100%; max-height:78vh; aspect-ratio:16/9; border-radius:12px; background:#000; object-fit:contain; }
.dramora-episode-controls a{text-decoration:none}.dramora-episode-controls input{accent-color:#a855f7}
@media(max-width:600px){.dramora-episode-controls{align-items:stretch!important}.dramora-episode-controls a{flex:1;text-align:center}.dramora-episode-controls label{width:100%;padding:5px 2px}}
.registered-player-note { margin:9px 2px 0; color:var(--muted); font-size:10px; }
.profile-panel { display:flex; align-items:center; gap:16px; padding:20px; margin-bottom:25px; border:1px solid var(--line);
  border-radius:16px; background:var(--surface); }
.profile-avatar { display:grid; flex:0 0 58px; width:58px; height:58px; place-items:center; overflow:hidden;
  border-radius:18px; background:rgba(155,92,255,.18); color:#e2d0ff; font-size:22px; font-weight:850; }
.profile-avatar img { width:100%; height:100%; object-fit:cover; }
.profile-panel h2 { margin:0 0 3px; font-size:18px; }
.profile-panel p { margin:0; color:var(--muted); font-size:12px; overflow-wrap:anywhere; }
.post-actions { display:flex; flex-wrap:wrap; gap:9px; margin:0 0 18px; }
.favorite-action { border:1px solid rgba(174,126,255,.35); border-radius:10px; padding:9px 13px; color:#e4d4ff; background:rgba(155,92,255,.12); font-size:12px; font-weight:800; }
.favorite-action.is-saved { border-color:rgba(255,79,145,.35); color:#ffc2da; background:rgba(255,79,145,.1); }
.dramora-toast { position:fixed; z-index:1100; left:50%; bottom:24px; transform:translate(-50%,18px); opacity:0; pointer-events:none;
  max-width:calc(100% - 28px); padding:12px 16px; border:1px solid var(--line); border-radius:12px;
  background:#1a1b2a; color:#fff; box-shadow:0 12px 40px rgba(0,0,0,.4); font-size:12px; transition:.2s ease; }
.dramora-toast.show { opacity:1; transform:translate(-50%,0); }
@media(max-width:900px) { .library-grid { grid-template-columns:repeat(3,minmax(0,1fr)); } }
@media(max-width:600px) {
  .auth-dialog { padding:24px 20px; border-radius:19px; }
  .library-grid { grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }
  .profile-panel { align-items:flex-start; padding:15px; }
}


/* DRAMORA V4 — authenticated community and private messages */
.community-shell { min-width:0; }
.community-tabs { display:flex; gap:8px; padding:5px; margin:0 0 16px; width:max-content; max-width:100%; border:1px solid var(--line); border-radius:13px; background:#0d0f19; }
.community-tab { border:0; border-radius:9px; padding:10px 15px; color:var(--muted); background:transparent; font-size:12px; font-weight:800; }
.community-tab.active { color:#fff; background:linear-gradient(110deg,rgba(155,92,255,.35),rgba(255,79,145,.18)); box-shadow:inset 0 0 0 1px rgba(190,150,255,.18); }
.community-panel { min-width:0; border:1px solid var(--line); border-radius:17px; background:linear-gradient(160deg,rgba(22,23,39,.98),rgba(13,15,25,.98)); overflow:hidden; }
.community-panel-head { display:flex; align-items:center; justify-content:space-between; gap:12px; padding:15px 17px; border-bottom:1px solid var(--line); }
.community-panel-head h2 { margin:0; font-size:15px; }
.community-panel-head p { margin:3px 0 0; color:var(--muted); font-size:11px; }
.community-status { display:inline-flex; align-items:center; gap:7px; color:#a9f0ce; font-size:10px; font-weight:800; white-space:nowrap; }
.community-status:before { content:""; width:7px; height:7px; border-radius:50%; background:#52d69a; box-shadow:0 0 12px rgba(82,214,154,.6); }
.community-messages { display:flex; flex-direction:column; gap:12px; min-height:270px; max-height:540px; overflow:auto; padding:16px; overscroll-behavior:contain; }
.community-message { min-width:0; padding:12px; border:1px solid rgba(255,255,255,.065); border-radius:13px; background:rgba(255,255,255,.025); }
.community-message-head { display:flex; align-items:center; flex-wrap:wrap; gap:7px; margin-bottom:7px; }
.community-message-name { color:#e8dcff; font-size:12px; font-weight:850; }
.community-message-time { color:#777b91; font-size:10px; }
.community-message-body { color:#e2e2ec; font-size:13px; line-height:1.65; overflow-wrap:anywhere; white-space:pre-wrap; }
.community-message-body a { color:#c7a5ff; text-decoration:underline; text-underline-offset:2px; overflow-wrap:anywhere; }
.community-reply-quote { margin:0 0 8px; padding:7px 10px; border-left:2px solid var(--purple); border-radius:0 8px 8px 0; color:#a7a8b8; background:rgba(155,92,255,.07); font-size:11px; }
.community-message-actions { display:flex; flex-wrap:wrap; gap:6px; margin-top:9px; }
.community-message-action { padding:5px 8px; border:1px solid rgba(255,255,255,.09); border-radius:8px; color:#b8b8c8; background:rgba(255,255,255,.035); font-size:10px; }
.community-message-action:hover,.community-message-action.is-active { border-color:rgba(155,92,255,.45); color:#e3d1ff; background:rgba(155,92,255,.12); }
.community-load-older { display:block; margin:12px auto 0; padding:8px 12px; border:1px solid var(--line); border-radius:9px; color:#cbb3ff; background:rgba(155,92,255,.08); font-size:11px; font-weight:750; }
.community-composer { padding:13px; border-top:1px solid var(--line); background:rgba(7,8,14,.35); }
.community-composer textarea { display:block; width:100%; min-height:76px; max-height:170px; resize:vertical; padding:12px 13px; border:1px solid var(--line); border-radius:11px; outline:none; color:#fff; background:#0a0c15; font:inherit; font-size:13px; line-height:1.5; }
.community-composer textarea:focus,.community-search:focus { border-color:rgba(174,126,255,.65); box-shadow:0 0 0 3px rgba(155,92,255,.1); }
.community-composer-foot { display:flex; align-items:center; justify-content:space-between; gap:10px; margin-top:9px; }
.community-hint { color:#777b91; font-size:10px; }
.community-send { min-width:92px; padding:9px 14px; border:0; border-radius:9px; color:#fff; background:linear-gradient(110deg,var(--purple),#7655ed 55%,var(--pink)); font-size:11px; font-weight:850; }
.community-send:disabled { opacity:.5; cursor:wait; }
.community-replying { display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:9px; padding:8px 10px; border-radius:9px; color:#cbb3ff; background:rgba(155,92,255,.1); font-size:11px; }
.community-replying button { border:0; color:#fff; background:transparent; font-size:16px; }
.community-private-layout { display:grid; grid-template-columns:minmax(210px, .72fr) minmax(0,1.55fr); min-height:490px; }
.community-private-sidebar { min-width:0; padding:14px; border-right:1px solid var(--line); }
.community-search { width:100%; padding:11px 12px; border:1px solid var(--line); border-radius:10px; outline:none; color:#fff; background:#0a0c15; font-size:12px; }
.community-search-results,.community-conversation-list { display:flex; flex-direction:column; gap:7px; margin-top:11px; }
.community-section-label { margin:17px 0 8px; color:#8d90a4; font-size:10px; font-weight:850; letter-spacing:1.2px; text-transform:uppercase; }
.community-person,.community-conversation { display:flex; align-items:center; gap:10px; width:100%; padding:10px; border:1px solid transparent; border-radius:11px; color:#eee; background:transparent; text-align:left; cursor:pointer; }
.community-person:hover,.community-conversation:hover,.community-conversation.active { border-color:rgba(155,92,255,.28); background:rgba(155,92,255,.09); }
.community-avatar { display:grid; flex:0 0 34px; width:34px; height:34px; place-items:center; overflow:hidden; border-radius:11px; color:#e7d8ff; background:linear-gradient(135deg,#47316b,#8c477e); font-size:12px; font-weight:850; }
.community-avatar img { width:100%; height:100%; object-fit:cover; }
.community-person-copy,.community-conversation-copy { display:block; min-width:0; flex:1; }
.community-person-copy strong,.community-conversation-copy strong { display:block; overflow:hidden; color:#e9e8f1; font-size:11px; text-overflow:ellipsis; white-space:nowrap; }
.community-person-copy small,.community-conversation-copy small { display:block; overflow:hidden; margin-top:3px; color:#85889b; font-size:10px; text-overflow:ellipsis; white-space:nowrap; }
.community-unread { display:grid; flex:0 0 19px; width:19px; height:19px; place-items:center; border-radius:50%; color:#fff; background:#8f59ed; font-size:9px; font-weight:850; }
.community-private-main { display:flex; min-width:0; flex-direction:column; }
.community-private-placeholder { display:grid; flex:1; min-height:350px; place-items:center; padding:25px; color:var(--muted); text-align:center; font-size:13px; }
.community-private-head { display:flex; align-items:center; justify-content:space-between; gap:10px; min-height:57px; padding:12px 15px; border-bottom:1px solid var(--line); }
.community-private-head strong { font-size:13px; }
.community-private-head button { border:1px solid var(--line); border-radius:8px; padding:6px 9px; color:#ffb9cb; background:rgba(255,79,145,.08); font-size:10px; }
.community-private-main .community-messages { flex:1; min-height:300px; max-height:490px; }
.community-error { margin:12px 14px; padding:10px 12px; border:1px solid rgba(255,100,130,.25); border-radius:9px; color:#ffb9c6; background:rgba(255,70,100,.08); font-size:11px; }
.community-muted { padding:12px 8px; color:#85889b; font-size:11px; line-height:1.6; }
@media(max-width:760px) {
  .community-private-layout { grid-template-columns:1fr; }
  .community-private-sidebar { border-right:0; border-bottom:1px solid var(--line); }
  .community-conversation-list { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); }
  .community-messages { max-height:52vh; }
  .community-private-main .community-messages { max-height:48vh; }
}
@media(max-width:420px) {
  .community-tabs { width:100%; }
  .community-tab { flex:1; padding:10px 8px; }
  .community-conversation-list { grid-template-columns:1fr; }
  .community-message { padding:10px; }
}


/* DRAMORA V5 — admin moderation and media management */
.admin-shell { display:grid; gap:18px; }
.admin-stats { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:12px; }
.admin-stat { padding:16px; border:1px solid var(--line); border-radius:14px; background:linear-gradient(145deg,#17172a,#10121e); }
.admin-stat strong { display:block; font-size:25px; letter-spacing:-.8px; }
.admin-stat span { color:var(--muted); font-size:11px; }
.admin-card { min-width:0; padding:17px; border:1px solid var(--line); border-radius:16px; background:var(--surface); }
.admin-card h2 { margin:0 0 5px; font-size:17px; }
.admin-card > p { margin:0 0 15px; color:var(--muted); font-size:12px; line-height:1.6; }
.admin-report-list,.admin-media-list { display:grid; gap:11px; }
.admin-report { padding:14px; border:1px solid rgba(255,255,255,.075); border-radius:13px; background:rgba(255,255,255,.025); }
.admin-report-head { display:flex; align-items:flex-start; justify-content:space-between; gap:10px; }
.admin-report-head strong { display:block; color:#eee8fb; font-size:12px; }
.admin-report-meta { color:#85889b; font-size:10px; line-height:1.6; overflow-wrap:anywhere; }
.admin-report-excerpt { margin:10px 0; padding:10px 12px; border-left:2px solid var(--purple); border-radius:0 9px 9px 0; background:rgba(155,92,255,.07); color:#d7d2e4; font-size:12px; line-height:1.6; white-space:pre-wrap; overflow-wrap:anywhere; }
.admin-status { display:inline-flex; align-items:center; padding:5px 8px; border:1px solid rgba(155,92,255,.28); border-radius:999px; color:#ddc9ff; background:rgba(155,92,255,.1); font-size:9px; font-weight:850; text-transform:uppercase; letter-spacing:.5px; white-space:nowrap; }
.admin-status.resolved { border-color:rgba(80,210,150,.25); color:#a9f0ce; background:rgba(60,190,130,.08); }
.admin-status.dismissed { border-color:rgba(255,255,255,.12); color:#aeb0bf; background:rgba(255,255,255,.04); }
.admin-actions { display:flex; flex-wrap:wrap; gap:7px; margin-top:11px; }
.admin-action { padding:8px 10px; border:1px solid var(--line); border-radius:9px; color:#e6dcf7; background:rgba(155,92,255,.09); font-size:10px; font-weight:800; }
.admin-action.danger { border-color:rgba(255,90,125,.25); color:#ffb9c6; background:rgba(255,70,100,.08); }
.admin-action:disabled { opacity:.45; cursor:wait; }
.admin-form-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; }
.admin-field { display:block; min-width:0; color:#d9d9e5; font-size:11px; font-weight:750; }
.admin-field input,.admin-field select,.admin-field textarea { display:block; width:100%; min-width:0; margin-top:6px; padding:11px 12px; border:1px solid var(--line); border-radius:10px; outline:none; color:#fff; background:#0a0c15; font:inherit; font-weight:500; }
.admin-field input:focus,.admin-field select:focus,.admin-field textarea:focus { border-color:rgba(174,126,255,.65); box-shadow:0 0 0 3px rgba(155,92,255,.1); }
.admin-field.full { grid-column:1/-1; }
.admin-check { display:flex; align-items:flex-start; gap:9px; color:var(--muted); font-size:11px; line-height:1.5; }
.admin-check input { margin-top:2px; accent-color:var(--purple); }
.admin-help { color:#85889b; font-size:10px; line-height:1.6; }
.admin-submit { min-height:42px; padding:0 15px; border:0; border-radius:10px; color:#fff; background:linear-gradient(110deg,var(--purple),#7655ed 55%,var(--pink)); font-size:11px; font-weight:850; }
.admin-submit:disabled { opacity:.5; cursor:wait; }
.admin-media-row { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; padding:12px; border:1px solid rgba(255,255,255,.07); border-radius:11px; }
.admin-media-row strong { display:block; color:#eee8fb; font-size:11px; overflow-wrap:anywhere; }
.admin-media-row small { display:block; margin-top:4px; color:#85889b; font-size:10px; line-height:1.5; overflow-wrap:anywhere; }
.admin-link { color:#c9aaff; font-size:10px; font-weight:800; text-decoration:underline; }
.admin-warning { padding:11px 12px; border:1px solid rgba(255,180,80,.2); border-radius:10px; color:#f4d6a1; background:rgba(255,180,80,.06); font-size:11px; line-height:1.6; }
.admin-denied { padding:25px; border:1px solid rgba(255,100,130,.22); border-radius:14px; color:#ffbdc9; background:rgba(255,70,100,.07); text-align:center; }
@media(max-width:600px) {
  .admin-stats { grid-template-columns:1fr 1fr; }
  .admin-form-grid { grid-template-columns:1fr; }
  .admin-field.full { grid-column:auto; }
  .admin-report-head,.admin-media-row { flex-direction:column; }
}

@media(max-width:1050px) { .drama-grid{grid-template-columns:repeat(4,minmax(0,1fr));} .search-box{width:180px;} }
@media(max-width:760px) {
  .nav{width:calc(100% - 28px);min-height:62px;gap:12px;}
  .nav-links{display:none;position:absolute;top:62px;left:0;right:0;padding:16px 20px 20px;background:#0c0d17;border-bottom:1px solid var(--line);flex-direction:column;align-items:flex-start;gap:16px;}
  .nav-links.open{display:flex;}
  .mobile-menu{display:block;} .search-box{display:none;} .nav-action{padding:9px 12px;font-size:12px;}
  .container{width:calc(100% - 28px);} .hero{padding:25px 0 18px;}
  .hero-panel{min-height:330px;border-radius:20px;background:linear-gradient(90deg,rgba(7,8,15,.96),rgba(7,8,15,.55)),radial-gradient(circle at 80% 25%,rgba(155,92,255,.5),transparent 45%),linear-gradient(135deg,#242039,#111321);}
  .hero-content{padding:25px 22px;} .hero h1{font-size:39px;letter-spacing:-1.5px;}
  .drama-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:15px;}
  .content-layout{grid-template-columns:1fr;} .sidebar{display:none;}
  .section-head h2{font-size:20px;}
}
@media(min-width:761px) and (max-width:900px){.drama-grid{grid-template-columns:repeat(3,minmax(0,1fr));}}

/* DRAMORA V9.9 — mobile bottom navigation */
.mobile-bottom-nav { display:none; }
@media(max-width:760px) {
  body { padding-bottom:calc(72px + env(safe-area-inset-bottom, 0px)); }
  .mobile-bottom-nav {
    position:fixed; left:0; right:0; bottom:0; z-index:900;
    display:grid; grid-template-columns:repeat(5,minmax(0,1fr));
    min-height:62px; padding:7px 8px calc(7px + env(safe-area-inset-bottom, 0px));
    border-top:1px solid rgba(190,150,255,.16);
    background:rgba(10,11,19,.94); backdrop-filter:blur(20px); -webkit-backdrop-filter:blur(20px);
    box-shadow:0 -10px 34px rgba(0,0,0,.28);
  }
  .mobile-bottom-item { min-width:0; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:2px; border-radius:12px; color:#918da3; font-size:10px; font-weight:700; line-height:1.2; text-decoration:none; -webkit-tap-highlight-color:transparent; }
  .mobile-bottom-icon { display:grid; place-items:center; width:27px; height:25px; font-size:23px; line-height:1; font-weight:500; }
  .mobile-bottom-item.active { color:#d9c2ff; background:rgba(155,92,255,.13); }
  .mobile-bottom-item.active .mobile-bottom-icon { color:#c59aff; text-shadow:0 0 16px rgba(169,112,255,.55); }
  .mobile-bottom-item:focus-visible { outline:2px solid #b78aff; outline-offset:-2px; }
}

/* V9.11 — Blogger Layout editor slots */
.layout-slot { display:block; width:100%; max-width:var(--content); margin:0 auto; padding-left:24px; padding-right:24px; }
.layout-slot:empty { display:none; }
.layout-slot .widget { margin:0 0 16px; }
.layout-slot .widget-content { color:var(--text); }
.layout-header-slot { padding-top:0; padding-bottom:8px; }
.layout-home-top-slot,.layout-home-after-hero-slot,.layout-home-bottom-slot { padding-top:10px; padding-bottom:10px; }
.layout-footer-slot { padding-top:14px; padding-bottom:8px; }
.layout-slot img { height:auto; max-width:100%; border-radius:12px; }
.layout-slot a { color:#c9a8ff; }
/* V9.12 — native Blogger LinkList and Label gadgets */
.nav-fallback-links { display:contents; }
.layout-nav-slot { display:contents; }
.layout-nav-slot .widget { margin:0; }
.layout-nav-slot .title { display:none; }
.layout-nav-slot .widget-content ul { display:flex; align-items:center; gap:24px; margin:0; padding:0; list-style:none; }
.layout-nav-slot .widget-content li { margin:0; padding:0; list-style:none; }
.layout-nav-slot .widget-content a { color:#c6c7d3; font-size:14px; white-space:nowrap; text-decoration:none; }
.layout-nav-slot .widget-content a:hover { color:#fff; }
.layout-category-slot { display:contents; }
.layout-category-slot .widget { margin:0; }
.layout-category-slot .title { display:none; }
.layout-category-slot .widget-content { display:flex; flex-wrap:wrap; gap:9px; }
.layout-category-slot .widget-content a { display:inline-flex; align-items:center; padding:8px 13px; border:1px solid var(--line); border-radius:999px; color:#c8c8d4; background:var(--surface); font-size:12px; text-decoration:none; }
.layout-category-slot .widget-content a:hover { color:#fff; border-color:rgba(155,92,255,.5); background:rgba(155,92,255,.15); }
.category-fallback-links { display:contents; }
@media(max-width:760px) {
  .layout-slot { padding-left:16px; padding-right:16px; }
  .layout-header-slot { padding-top:4px; }
  .layout-nav-slot .widget-content ul { flex-direction:column; align-items:flex-start; gap:16px; }
  .layout-nav-slot .widget-content a { font-size:14px; }
}

/* DRAMORA V10 — reference-led editorial layout system */
.home-page-container { padding-top:18px; }
.home-content-layout { grid-template-columns:minmax(0,1fr) 286px; gap:28px; align-items:start; }
.home-main-column { min-width:0; }
.home-main-column .hero { padding-top:24px; }
.home-main-column .drama-grid { grid-template-columns:repeat(3,minmax(0,1fr)); gap:16px; }
.home-main-column .continue-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
.home-sidebar,.blog-sidebar { min-width:0; position:relative; }
.home-sidebar { padding-top:26px; }
.sidebar-box { background:linear-gradient(145deg,rgba(24,25,42,.96),rgba(15,16,27,.98)); border-color:rgba(255,255,255,.085); }
.sidebar-feature-box { padding:21px; background:radial-gradient(circle at 100% 0,rgba(155,92,255,.22),transparent 48%),linear-gradient(145deg,#1b1830,#111320 72%); border-color:rgba(174,126,255,.22); }
.sidebar-feature-box h3 { margin:10px 0 8px; font-size:19px; line-height:1.25; letter-spacing:-.35px; }
.sidebar-feature-box p { margin:0 0 16px; line-height:1.65; }
.sidebar-feature-box .button-primary { width:100%; padding:10px 12px; font-size:12px; }
.sidebar-link-list { display:grid; gap:2px; }
.sidebar-link-list a { display:flex; align-items:center; justify-content:space-between; padding:9px 10px; color:#c9c6d6; border-radius:9px; font-size:13px; }
.sidebar-link-list a:after { content:'›'; color:#a78bfa; font-size:18px; }
.sidebar-link-list a:hover { color:#fff; background:rgba(155,92,255,.12); }
.layout-sidebar-slot .widget { margin:0 0 16px; padding:17px; border:1px solid var(--line); border-radius:var(--radius); background:var(--surface); }
.layout-sidebar-slot .widget-title { margin:0 0 12px; color:#fff; font-size:15px; }
.layout-sidebar-slot .widget-content { color:var(--muted); font-size:13px; }
.blog-content-container { padding-top:34px; }
.blog-content-layout { grid-template-columns:minmax(0,1fr) 286px; gap:28px; align-items:start; }
.blog-content-posts { min-width:0; }
.post-page-heading,.archive-page-heading { margin:0 0 17px; padding:0 0 14px; border-bottom:1px solid var(--line); }
.archive-page-heading h1 { margin:5px 0 0; font-size:25px; letter-spacing:-.7px; }
.archive-page-heading p,.post-page-heading p { margin:5px 0 0; }
.archive-post-feed { display:grid; gap:14px; }
.archive-post-feed .post-outer { margin:0; }
.archive-post-feed .post { display:grid; grid-template-columns:minmax(150px,220px) minmax(0,1fr); gap:18px; align-items:start; padding:15px; }
.archive-post-thumb { display:block; grid-row:1 / span 2; min-width:0; aspect-ratio:3/4; overflow:hidden; border-radius:12px; background:#171827; }
.archive-post-thumb img { width:100%; height:100%; object-fit:cover; }
.archive-post-feed .post-header { min-width:0; }
.archive-post-feed .post-title { font-size:19px; margin:2px 0 9px; }
.archive-post-feed .post-body { min-width:0; font-size:13px; line-height:1.65; }
.archive-post-feed .post-body p { margin:0 0 10px; }
.archive-post-feed .post-labels { grid-column:1/-1; }
.archive-post-feed .post-title a:hover { color:#d8c3ff; }
.dramora-pager { justify-content:space-between; margin:22px 0 8px; }
.dramora-pager a { border-color:rgba(174,126,255,.24); background:rgba(155,92,255,.09); }
.single-post-feed .post { padding:clamp(20px,3vw,34px); }
.single-post-feed .post-title { font-size:clamp(27px,3.4vw,40px); }
.single-post-feed .post-body { font-size:15px; line-height:1.85; }
@media(max-width:980px) {
  .home-content-layout,.blog-content-layout { grid-template-columns:minmax(0,1fr) 250px; gap:18px; }
  .home-main-column .drama-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
}
@media(max-width:760px) {
  .home-content-layout,.blog-content-layout { grid-template-columns:minmax(0,1fr); gap:4px; }
  .home-sidebar { padding-top:8px; }
  .home-main-column .hero { padding-top:16px; }
  .home-main-column .drama-grid { grid-template-columns:repeat(2,minmax(0,1fr)); gap:11px; }
  .home-main-column .continue-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .blog-content-container { padding-top:20px; }
  .blog-sidebar { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; }
  .blog-sidebar > * { min-width:0; margin:0; }
  .archive-post-feed .post { grid-template-columns:112px minmax(0,1fr); gap:12px; padding:11px; }
  .archive-post-feed .post-title { font-size:15px; }
  .archive-post-feed .post-body { font-size:12px; }
  .archive-post-feed .post-labels { grid-column:1/-1; }
}
@media(max-width:420px) {
  .blog-sidebar { grid-template-columns:minmax(0,1fr); }
  .archive-post-feed .post { grid-template-columns:1fr; }
  .archive-post-feed .post-title { font-size:17px; }
}

body.script:
//
(function () {
  var navSlot = document.getElementById('dramoraNavWidgets');
  var navFallback = document.getElementById('navFallbackLinks');
  if (navSlot && navFallback && navSlot.querySelector('.widget')) navFallback.hidden = true;
  var categorySlot = document.getElementById('dramoraCategoryWidgets');
  var categoryFallback = document.getElementById('categoryFallbackLinks');
  if (categorySlot && categoryFallback && categorySlot.querySelector('.widget')) categoryFallback.hidden = true;
  var toggle = document.getElementById('menuToggle');
  var nav = document.getElementById('mainNav');
  if (toggle && nav) toggle.addEventListener('click', function () { nav.classList.toggle('open'); });
  var bottomNav = document.getElementById('mobileBottomNav');
  if (bottomNav) {
    var currentPath = window.location.pathname.replace(/\/+$/, '') || '/';
    var navItems = bottomNav.querySelectorAll('[data-nav]');
    navItems.forEach(function (item) {
      var key = item.getAttribute('data-nav');
      var target = new URL(item.href, window.location.href).pathname.replace(/\/+$/, '') || '/';
      var active = currentPath === target;
      if (active) { item.classList.add('active'); item.setAttribute('aria-current','page'); }
      else { item.classList.remove('active'); item.removeAttribute('aria-current'); }
    });
  }
  var search = document.getElementById('siteSearch');
  if (search) search.addEventListener('keydown', function (event) {
    if (event.key === 'Enter' && search.value.trim()) {
      window.location.href = '/search?q=' + encodeURIComponent(search.value.trim());
    }
  });

  // Make Blogger-uploaded videos and supported embeds fit the responsive player area.
  var postBodies = document.querySelectorAll('.post-body');
  postBodies.forEach(function (body) {
    var videos = body.querySelectorAll('video');
    videos.forEach(function (video) {
      video.setAttribute('controls', 'controls');
      video.setAttribute('playsinline', 'playsinline');
      video.setAttribute('preload', 'metadata');
      if (!video.parentElement.classList.contains('drama-player') &&
          !video.parentElement.classList.contains('episode-player') &&
          !video.parentElement.classList.contains('video-container')) {
        var wrap = document.createElement('div');
        wrap.className = 'episode-player';
        video.parentNode.insertBefore(wrap, video);
        wrap.appendChild(video);
      }
    });

    // Blogger video embeds commonly use iframe; keep their dimensions responsive.
    body.querySelectorAll('iframe').forEach(function (frame) {
      if (!frame.closest('.drama-player, .episode-player, .video-container')) {
        var holder = document.createElement('div');
        holder.className = 'episode-player';
        frame.parentNode.insertBefore(holder, frame);
        holder.appendChild(frame);
      }
      frame.setAttribute('allowfullscreen', 'allowfullscreen');
      frame.setAttribute('loading', 'lazy');
    });

    // Do not let user-provided links silently replace the drama platform tab.
    body.querySelectorAll('a[href]').forEach(function (link) {
      var href = link.getAttribute('href') || '';
      if (/^https?:\/\//i.test(href) && link.hostname !== window.location.hostname) {
        link.setAttribute('target', '_blank');
        link.setAttribute('rel', 'noopener noreferrer');
      }
    });
  });
}());

// DRAMORA V3 — Firebase Authentication and personal Firestore data.
(function () {
  'use strict';

  var firebaseConfig = {
    apiKey: 'REPLACE_WITH_FIREBASE_WEB_API_KEY',
    authDomain: 'REPLACE_WITH_PROJECT_ID.firebaseapp.com',
    projectId: 'REPLACE_WITH_PROJECT_ID',
    appId: 'REPLACE_WITH_FIREBASE_APP_ID'
  };
  // If the project ID is filled but authDomain was left at its default marker,
  // derive the standard Firebase Auth domain. A custom auth domain may be kept.
  if (firebaseConfig.projectId.indexOf('REPLACE_') !== 0 &&
      firebaseConfig.authDomain.indexOf('REPLACE_') === 0) {
    firebaseConfig.authDomain = firebaseConfig.projectId + '.firebaseapp.com';
  }

  // Set this to the deployed Cloudflare Worker origin, without a trailing slash.
  var DRAMORA_MEDIA_API_URL = 'REPLACE_WITH_CLOUDFLARE_WORKER_URL';

  var modal = document.getElementById('authModal');
  var authOpenBtn = document.getElementById('authOpenBtn');
  var authForm = document.getElementById('authForm');
  var authError = document.getElementById('authError');
  var authSuccess = document.getElementById('authSuccess');
  var signedInPanel = document.getElementById('authSignedInPanel');
  var verificationPanel = document.getElementById('authVerificationPanel');
  var mode = 'login';
  var auth = null;
  var db = null;
  var currentUser = null;
  var firebaseReady = false;
  var persistenceReady = Promise.resolve();
  var toastTimer = null;
  var isAdminUser = false;
  var adminClaimsReady = false;
  var adminReportsUnsubscribe = null;
  var adminPageRoot = null;

  function el(id) { return document.getElementById(id); }
  function safeUrl(value) {
    if (!value) return '';
    try {
      var url = new URL(value, window.location.origin);
      return (url.protocol === 'https:' || url.protocol === 'http:') ? url.href : '';
    } catch (error) { return ''; }
  }
  function notify(message) {
    var toast = el('dramoraToast');
    if (!toast) return;
    toast.textContent = message;
    toast.classList.add('show');
    window.clearTimeout(toastTimer);
    toastTimer = window.setTimeout(function () { toast.classList.remove('show'); }, 2800);
  }
  function clearMessages() {
    authError.hidden = true;
    authSuccess.hidden = true;
    authError.textContent = '';
    authSuccess.textContent = '';
  }
  function showError(message) {
    authError.textContent = message;
    authError.hidden = false;
    authSuccess.hidden = true;
  }
  function showSuccess(message) {
    authSuccess.textContent = message;
    authSuccess.hidden = false;
    authError.hidden = true;
  }
  function friendlyError(error) {
    var code = error && error.code ? error.code : '';
    var messages = {
      'auth/email-already-in-use': 'This email is already registered. Try signing in.',
      'auth/invalid-email': 'Please enter a valid email address.',
      'auth/weak-password': 'Choose a stronger password with at least 8 characters.',
      'auth/user-not-found': 'No account was found for this email.',
      'auth/wrong-password': 'The password is incorrect.',
      'auth/invalid-credential': 'The email or password is incorrect.',
      'auth/too-many-requests': 'Too many attempts. Please wait and try again.',
      'auth/popup-closed-by-user': 'The Google sign-in window was closed before completion.',
      'auth/popup-blocked': 'Your browser blocked the sign-in window. Allow pop-ups and try again.',
      'auth/unauthorized-domain': 'This Blogger domain is not authorized in Firebase Authentication.',
      'auth/network-request-failed': 'Network error. Check your connection and try again.'
    };
    return messages[code] || 'Something went wrong. Please try again.';
  }
  function setMode(nextMode) {
    mode = nextMode;
    clearMessages();
    var signup = mode === 'signup';
    el('authTitle').textContent = signup ? 'Create your account' : 'Welcome back';
    el('authSubtitle').textContent = signup
      ? 'Create a free account to save dramas and sync your progress.'
      : 'Sign in to save your dramas and continue watching.';
    el('authDisplayNameWrap').hidden = !signup;
    el('authConfirmWrap').hidden = !signup;
    el('authGoogleBtn').hidden = signup;
    el('authForgotBtn').hidden = signup;
    el('authSubmitBtn').textContent = signup ? 'Create free account' : 'Sign in';
    el('authModeSwitchBtn').textContent = signup
      ? 'Already have an account? Sign in'
      : 'New to Dramora? Create a free account';
    authForm.hidden = false;
    signedInPanel.hidden = true;
    verificationPanel.hidden = true;
    el('authModeSwitchBtn').hidden = false;
  }
  function renderSignedIn(user) {
    if (!user) return;
    clearMessages();
    authForm.hidden = true;
    el('authGoogleBtn').hidden = true;
    el('authForgotBtn').hidden = true;
    el('authModeSwitchBtn').hidden = true;
    signedInPanel.hidden = false;
    el('authTitle').textContent = 'You are signed in';
    el('authSubtitle').textContent = 'Your Dramora account is ready.';
    el('authAccountName').textContent = user.displayName || 'Dramora member';
    el('authAccountEmail').textContent = user.email || '';
    verificationPanel.hidden = !!user.emailVerified;
  }
  function openModal() {
    if (!modal) return;
    clearMessages();
    modal.classList.add('is-open');
    modal.setAttribute('aria-hidden', 'false');
    document.body.classList.add('modal-open');
    if (currentUser) renderSignedIn(currentUser);
    else {
      setMode(mode);
      if (!firebaseReady) showError('Firebase is not configured yet. Add your Firebase Web App values in the Blogger XML and complete the setup guide.');
      window.setTimeout(function () { el('authEmail').focus(); }, 40);
    }
  }
  function closeModal() {
    if (!modal) return;
    modal.classList.remove('is-open');
    modal.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('modal-open');
  }
  if (authOpenBtn) authOpenBtn.addEventListener('click', openModal);
  el('authCloseBtn').addEventListener('click', closeModal);
  modal.addEventListener('click', function (event) {
    if (event.target && event.target.getAttribute('data-auth-close') === 'true') closeModal();
  });
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape' && modal.classList.contains('is-open')) closeModal();
  });
  el('authModeSwitchBtn').addEventListener('click', function () {
    setMode(mode === 'login' ? 'signup' : 'login');
  });

  var configReady = firebaseConfig.apiKey.indexOf('REPLACE_') !== 0 &&
    firebaseConfig.projectId.indexOf('REPLACE_') !== 0 &&
    firebaseConfig.appId.indexOf('REPLACE_') !== 0 &&
    firebaseConfig.authDomain.indexOf('REPLACE_') !== 0 &&
    window.firebase && typeof window.firebase.initializeApp === 'function' &&
    typeof window.firebase.auth === 'function' &&
    typeof window.firebase.firestore === 'function';

  var profileSyncTasks = Object.create(null);
  var bloggerFeedCache = Object.create(null);
  function syncProfile(user) {
    if (!db || !user || !user.uid) return Promise.resolve(null);
    if (profileSyncTasks[user.uid]) return profileSyncTasks[user.uid];
    var uid = user.uid;
    var ref = db.collection('users').doc(uid);
    var displayName = (user.displayName || 'Dramora member').trim().slice(0, 60) || 'Dramora member';
    var photoURL = safeUrl(user.photoURL) || '';
    var task = ref.get().then(function (snapshot) {
      var payload = {
        uid: uid,
        email: user.email || '',
        displayName: displayName,
        photoURL: photoURL,
        emailVerified: !!user.emailVerified,
        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
      };
      if (!snapshot.exists) payload.createdAt = firebase.firestore.FieldValue.serverTimestamp();
      return ref.set(payload, { merge: true }).then(function () {
        var publicPayload = {
          uid: uid,
          displayName: displayName,
          photoURL: photoURL,
          searchName: displayName.toLowerCase(),
          updatedAt: firebase.firestore.FieldValue.serverTimestamp()
        };
        return db.collection('publicProfiles').doc(uid).set(publicPayload, { merge: true }).then(function () { return payload; });
      });
    });
    profileSyncTasks[uid] = task.finally(function () { delete profileSyncTasks[uid]; });
    return profileSyncTasks[uid];
  }

  function requireUser() {
    if (!auth || !auth.currentUser) return Promise.reject(new Error('Please sign in to use this feature.'));
    return Promise.resolve(auth.currentUser);
  }
  function encodeDocId(value) {
    var bytes = new TextEncoder().encode(String(value));
    var binary = '';
    for (var i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
    var encoded = window.btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
    if (!encoded || encoded.length > 900) throw new Error('This content identifier is too long.');
    return encoded;
  }
  function normalizeItem(item) {
    item = item || {};
    var contentUrl = safeUrl(item.contentUrl || item.url || window.location.href);
    if (!contentUrl) throw new Error('A valid content URL is required.');
    return {
      contentId: String(item.contentId || contentUrl).slice(0, 2048),
      title: String(item.title || 'Untitled drama').trim().slice(0, 160) || 'Untitled drama',
      contentUrl: contentUrl,
      posterUrl: safeUrl(item.posterUrl || item.imageUrl) || ''
    };
  }
  function pageQuery(collectionName, orderField, pageSize, cursor) {
    return requireUser().then(function (user) {
      var query = db.collection('users').doc(user.uid).collection(collectionName)
        .orderBy(orderField, 'desc').limit(Math.max(1, Math.min(Number(pageSize) || 20, 50)));
      if (cursor) query = query.startAfter(cursor);
      return query.get().then(function (snapshot) {
        return {
          items: snapshot.docs.map(function (doc) { return Object.assign({ id: doc.id }, doc.data()); }),
          nextCursor: snapshot.docs.length === Math.max(1, Math.min(Number(pageSize) || 20, 50))
            ? snapshot.docs[snapshot.docs.length - 1] : null
        };
      });
    });
  }

  var DramoraData = {
    addFavorite: function (item) {
      var normalized = normalizeItem(item);
      return requireUser().then(function (user) {
        return db.collection('users').doc(user.uid).collection('favorites')
          .doc(encodeDocId(normalized.contentId)).set({
            contentId: normalized.contentId, title: normalized.title,
            contentUrl: normalized.contentUrl, posterUrl: normalized.posterUrl,
            addedAt: firebase.firestore.FieldValue.serverTimestamp()
          });
      });
    },
    removeFavorite: function (contentId) {
      return requireUser().then(function (user) {
        return db.collection('users').doc(user.uid).collection('favorites')
          .doc(encodeDocId(contentId)).delete();
      });
    },
    isFavorite: function (contentId) {
      return requireUser().then(function (user) {
        return db.collection('users').doc(user.uid).collection('favorites')
          .doc(encodeDocId(contentId)).get().then(function (snapshot) { return snapshot.exists; });
      });
    },
    listFavorites: function (pageSize, cursor) {
      return pageQuery('favorites', 'addedAt', pageSize, cursor);
    },
    listWatchHistory: function (pageSize, cursor) {
      return pageQuery('watchHistory', 'lastWatchedAt', pageSize, cursor);
    },
    getWatchProgress: function (contentId) {
      return requireUser().then(function (user) {
        return db.collection('users').doc(user.uid).collection('watchProgress')
          .doc(encodeDocId(contentId)).get().then(function (snapshot) {
            return snapshot.exists ? snapshot.data() : null;
          });
      });
    },
    saveWatchProgress: function (item) {
      var normalized = normalizeItem(item);
      var position = Math.max(0, Math.min(Number(item.positionSeconds) || 0, 86400));
      var duration = Math.max(0, Math.min(Number(item.durationSeconds) || 0, 86400));
      var completed = !!item.completed;
      return requireUser().then(function (user) {
        var userRef = db.collection('users').doc(user.uid);
        var docId = encodeDocId(normalized.contentId);
        var stamp = firebase.firestore.FieldValue.serverTimestamp();
        var batch = db.batch();
        batch.set(userRef.collection('watchProgress').doc(docId), {
          contentId: normalized.contentId, title: normalized.title,
          contentUrl: normalized.contentUrl, posterUrl: normalized.posterUrl,
          positionSeconds: position, durationSeconds: duration,
          completed: completed, updatedAt: stamp
        }, { merge: true });
        batch.set(userRef.collection('watchHistory').doc(docId), {
          contentId: normalized.contentId, title: normalized.title,
          contentUrl: normalized.contentUrl, posterUrl: normalized.posterUrl,
          positionSeconds: position, durationSeconds: duration,
          lastWatchedAt: stamp, updatedAt: stamp
        }, { merge: true });
        return batch.commit();
      });
    },
    getProfile: function () {
      return requireUser().then(function (user) {
        return db.collection('users').doc(user.uid).get().then(function (snapshot) {
          return snapshot.exists ? snapshot.data() : null;
        });
      });
    }
  };
  window.DramoraData = DramoraData;

  function currentContent() {
    var canonical = document.querySelector('link[rel="canonical"]');
    var titleNode = document.querySelector('.post-title.entry-title, .post-title');
    var imageNode = document.querySelector('.post-body .dramora-thumbnail img, .post-body .dramora-series-cover, .post-body .separator img, .post-body img');
    var ogImage = document.querySelector('meta[property="og:image"]');
    return normalizeItem({
      contentId: safeUrl(canonical && canonical.href) || window.location.href,
      contentUrl: safeUrl(canonical && canonical.href) || window.location.href,
      title: titleNode ? titleNode.textContent.trim() : document.title,
      posterUrl: imageNode ? imageNode.src : (ogImage ? ogImage.content : '')
    });
  }
  function normalizeMediaLinkMeta(rawUrl, rawDramaKey, rawEpisodeNumber, rawEpisodeTitle) {
    var linkedPostUrl = '';
    var urlText = String(rawUrl || '').trim();
    if (urlText) {
      linkedPostUrl = safeUrl(urlText);
      if (!linkedPostUrl || !/^https:\/\//i.test(linkedPostUrl) || new URL(linkedPostUrl).origin !== window.location.origin) {
        throw new Error('Use the canonical HTTPS URL of a Blogger post on this Dramora blog.');
      }
    }
    var dramaKey = String(rawDramaKey || '').trim().toLowerCase().slice(0, 80);
    if (dramaKey && !/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(dramaKey)) {
      throw new Error('Drama key must use lowercase letters, numbers and single hyphens only.');
    }
    var episodeText = String(rawEpisodeNumber || '').trim();
    var episodeNumber = episodeText ? Number(episodeText) : 0;
    if (!Number.isInteger(episodeNumber) || episodeNumber < 0 || episodeNumber > 9999) {
      throw new Error('Episode number must be a whole number between 1 and 9999, or left blank.');
    }
    var episodeTitle = String(rawEpisodeTitle || '').trim().slice(0, 160);
    if (!linkedPostUrl && (dramaKey || episodeNumber || episodeTitle)) {
      throw new Error('Add the Blogger post URL before entering episode details.');
    }
    return { linkedPostUrl: linkedPostUrl, dramaKey: dramaKey, episodeNumber: episodeNumber, episodeTitle: episodeTitle };
  }

  var registeredPlayerLookups = Object.create(null);
  function findNativeBloggerVideo(body) {
    if (!body) return null;
    return body.querySelector('object.BLOG_video_class, object[id^="BLOG_video-"], iframe.BLOG_video_class, iframe[id^="BLOG_video-"]');
  }
  function prepareNativeBloggerPost(body) {
    if (!body) return false;
    var nativeVideo = findNativeBloggerVideo(body);
    if (!nativeVideo) return false;
    nativeVideo.classList.add('dramora-native-video');
    if (!nativeVideo.getAttribute('aria-label')) nativeVideo.setAttribute('aria-label', 'Blogger uploaded episode video');
    var poster = Array.prototype.slice.call(body.querySelectorAll('.separator img, img')).find(function (img) { return !img.closest('.dramora-thumbnail'); }) || null;
    if (poster) {
      poster.classList.add('dramora-episode-poster');
      if (!poster.getAttribute('alt')) poster.setAttribute('alt', 'Episode poster');
      poster.loading = 'eager';
      poster.decoding = 'async';
    }
    body.dataset.dramoraNativeVideo = 'true';
    return true;
  }
  function buildHybridSeriesExperience(body) {
    if (!body || body.dataset.dramoraHybridReady === 'true') return body && body.dataset.dramoraHybridReady === 'true';
    var episodeNodes = Array.prototype.slice.call(body.querySelectorAll('.dramora-episodes > .dramora-episode[ep-id], .dramora-episodes .dramora-episode[ep-id]'));
    if (!episodeNodes.length) return false;
    var used = Object.create(null), episodes = [];
    episodeNodes.forEach(function (node) {
      var idText = String(node.getAttribute('ep-id') || '').trim();
      if (!/^\d{1,4}$/.test(idText)) return;
      var number = Number(idText);
      if (!number || used[number]) return;
      var media = node.querySelector('object.BLOG_video_class, object[id^="BLOG_video-"], iframe.BLOG_video_class, iframe[id^="BLOG_video-"], video, iframe');
      if (!media) return;
      used[number] = true;
      var descriptionNode = node.querySelector('description.dramora-episode-description, .dramora-episode-description, description');
      var description = descriptionNode ? descriptionNode.textContent.trim() : '';
      var title = String(node.getAttribute('ep-title') || node.getAttribute('data-episode-title') || ('Episode ' + number)).trim().slice(0,120);
      episodes.push({ id:number, title:title, description:description.slice(0,1200), media:media });
    });
    episodes.sort(function (a,b) { return a.id-b.id; });
    if (!episodes.length) return false;
    var seriesDescriptionNode = body.querySelector('description.dramora-series-description, .dramora-series-description');
    if (!seriesDescriptionNode) {
      seriesDescriptionNode = Array.prototype.slice.call(body.querySelectorAll('description')).find(function (node) {
        return !node.closest('.dramora-episode');
      }) || null;
    }
    var seriesDescription = seriesDescriptionNode ? seriesDescriptionNode.textContent.trim() : '';
    var poster = body.querySelector('.dramora-thumbnail img, .dramora-series-cover') || Array.prototype.slice.call(body.querySelectorAll('.separator img, img')).find(function (img) {
      return !img.closest('.dramora-episode') && !img.closest('.dramora-thumbnail');
    }) || null;
    var titleNode = document.querySelector('.post-title.entry-title, .post-title');
    var seriesTitle = titleNode ? titleNode.textContent.trim() : document.title;
    var host = document.createElement('section'); host.className = 'dramora-hybrid-series';
    var overview = document.createElement('header'); overview.className = 'dramora-series-overview';
    if (poster) {
      poster.classList.add('dramora-series-cover');
      poster.alt = poster.alt || (seriesTitle + ' poster');
      poster.loading = 'eager'; poster.decoding = 'async';
      var posterWrapper = poster.parentElement;
      poster.remove();
      if (posterWrapper && posterWrapper.classList.contains('separator') && !posterWrapper.textContent.trim() && posterWrapper.children.length === 0) posterWrapper.remove();
    }
    var summary = document.createElement('div');
    var heading = document.createElement('h2'); heading.textContent = seriesTitle;
    var description = document.createElement('div'); description.className = 'dramora-series-description';
    description.textContent = seriesDescription || 'Explore the episodes of this series.';
    summary.appendChild(heading); summary.appendChild(description); overview.appendChild(summary);
    var playerPanel = document.createElement('section'); playerPanel.className = 'dramora-hybrid-player';
    playerPanel.setAttribute('aria-label','Episode player');
    var playerTitle = document.createElement('h3');
    var playerSlot = document.createElement('div'); playerSlot.className = 'dramora-hybrid-player-slot';
    var episodeDescription = document.createElement('p'); episodeDescription.className = 'dramora-current-episode-description';
    playerPanel.appendChild(playerTitle); playerPanel.appendChild(playerSlot); playerPanel.appendChild(episodeDescription);
    var listHeading = document.createElement('h3'); listHeading.className = 'dramora-episode-heading'; listHeading.textContent = 'Episodes';
    var list = document.createElement('div'); list.className = 'dramora-hybrid-episode-list'; list.setAttribute('role','group'); list.setAttribute('aria-label','Choose an episode');
    host.appendChild(overview); host.appendChild(playerPanel); host.appendChild(listHeading); host.appendChild(list);
    var requested = Number(new URLSearchParams(window.location.search).get('ep')) || episodes[0].id;
    var active = episodes.find(function (entry) { return entry.id === requested; }) || episodes[0];
    function selectEpisode(entry, updateUrl) {
      active = entry;
      playerTitle.textContent = entry.title;
      playerSlot.replaceChildren(entry.media);
      if (entry.media.tagName === 'OBJECT' || entry.media.tagName === 'IFRAME') {
        entry.media.classList.add('dramora-native-video');
        entry.media.setAttribute('aria-label', seriesTitle + ' ' + entry.title);
        entry.media.style.width = '100%'; entry.media.style.maxWidth = '100%';
      }
      episodeDescription.textContent = entry.description;
      Array.prototype.forEach.call(list.children, function (button) {
        var selected = Number(button.getAttribute('data-episode-id')) === entry.id;
        button.classList.toggle('is-active', selected);
        button.setAttribute('aria-pressed', selected ? 'true' : 'false');
      });
      if (updateUrl && window.history && window.history.replaceState) {
        var url = new URL(window.location.href); url.searchParams.set('ep', String(entry.id));
        window.history.replaceState({}, '', url.pathname + url.search + url.hash);
      }
    }
    episodes.forEach(function (entry) {
      var button = document.createElement('button'); button.type = 'button'; button.className = 'dramora-hybrid-episode';
      button.setAttribute('data-episode-id',String(entry.id)); button.setAttribute('aria-pressed','false');
      var number = document.createElement('span'); number.className = 'dramora-hybrid-episode-number'; number.textContent = 'EP ' + entry.id;
      var copy = document.createElement('span'); copy.className = 'dramora-hybrid-episode-copy';
      var name = document.createElement('strong'); name.textContent = entry.title;
      var meta = document.createElement('small'); meta.textContent = entry.description ? 'Episode details' : 'Free episode';
      copy.appendChild(name); copy.appendChild(meta); button.appendChild(number); button.appendChild(copy);
      button.addEventListener('click',function(){ selectEpisode(entry,true); });
      list.appendChild(button);
    });
    body.replaceChildren(host);
    body.dataset.dramoraHybridReady = 'true';
    selectEpisode(active,false);
    return true;
  }

  function attachRegisteredMediaPlayer() {
    if (window.location.pathname.indexOf('/p/') === 0) return;
    var body = document.querySelector('.post-body');
    if (!body || body.dataset.dramoraMediaLookup === 'done' || body.dataset.dramoraMediaLookup === 'loading') return;
    if (buildHybridSeriesExperience(body) || prepareNativeBloggerPost(body) || body.querySelector('video, iframe')) { body.dataset.dramoraMediaLookup = 'done'; return; }
    if (!db) return;
    var item;
    try { item = currentContent(); } catch (error) { return; }
    body.dataset.dramoraMediaLookup = 'loading';
    var queryKey = item.contentUrl;
    if (registeredPlayerLookups[queryKey]) {
      registeredPlayerLookups[queryKey].then(function (asset) { mountRegisteredPlayer(body, item, asset); });
      return;
    }
    registeredPlayerLookups[queryKey] = db.collection('mediaAssets')
      .where('linkedPostUrl', '==', queryKey)
      .where('mediaType', '==', 'video')
      .where('status', '==', 'ready')
      .where('visibility', '==', 'public')
      .limit(1).get().then(function (snapshot) {
        if (snapshot.empty) return null;
        return snapshot.docs[0].data();
      }).catch(function (error) {
        delete registeredPlayerLookups[queryKey];
        throw error;
      });
    registeredPlayerLookups[queryKey].then(function (asset) {
      mountRegisteredPlayer(body, item, asset);
    }).catch(function (error) {
      body.dataset.dramoraMediaLookup = '';
      console.warn('Dramora registered media lookup failed:', error);
    });
  }
  function mountRegisteredPlayer(body, item, asset) {
    if (!body || !body.isConnected) return;
    if (!asset || body.querySelector('video, iframe')) { body.dataset.dramoraMediaLookup = 'done'; return; }
    var mediaUrl = safeUrl(asset.mediaUrl);
    if (!mediaUrl || !/^https:\/\//i.test(mediaUrl)) { body.dataset.dramoraMediaLookup = 'done'; return; }
    var section = document.createElement('section'); section.className = 'registered-player';
    var heading = document.createElement('h2'); heading.textContent = String(asset.episodeTitle || asset.title || item.title || 'Watch episode');
    var video = document.createElement('video'); video.controls = true; video.playsInline = true;
    video.preload = 'metadata'; video.setAttribute('aria-label', heading.textContent); video.setAttribute('controlsList', 'nodownload');
    var source = document.createElement('source'); source.src = mediaUrl;
    if (asset.mimeType && asset.mimeType !== 'video/*') source.type = String(asset.mimeType).slice(0, 100);
    video.appendChild(source);
    if (item.posterUrl) video.poster = item.posterUrl;
    var note = document.createElement('p'); note.className = 'registered-player-note';
    note.textContent = 'Official Dramora episode stream · ' + String(asset.storageProvider || 'media').toUpperCase();
    var nav = document.createElement('div'); nav.className = 'dramora-episode-controls';
    nav.style.cssText = 'display:flex;align-items:center;flex-wrap:wrap;gap:9px;margin:12px 0;';
    var previous = document.createElement('a'); previous.className = 'series-back'; previous.textContent = '← Previous episode'; previous.hidden = true;
    var next = document.createElement('a'); next.className = 'series-back'; next.textContent = 'Next episode →'; next.hidden = true;
    var autoLabel = document.createElement('label'); autoLabel.style.cssText = 'display:inline-flex;align-items:center;gap:7px;color:#b9b6c9;font-size:12px;';
    var auto = document.createElement('input'); auto.type = 'checkbox';
    try { auto.checked = window.localStorage.getItem('dramora-autoplay-next') === '1'; } catch (error) { auto.checked = false; }
    auto.addEventListener('change', function () { try { window.localStorage.setItem('dramora-autoplay-next', auto.checked ? '1' : '0'); } catch (error) {} });
    autoLabel.appendChild(auto); autoLabel.appendChild(document.createTextNode('Autoplay next episode'));
    nav.appendChild(previous); nav.appendChild(next); nav.appendChild(autoLabel);
    section.appendChild(heading); section.appendChild(video); section.appendChild(nav); section.appendChild(note);
    body.insertBefore(section, body.firstChild); body.dataset.dramoraMediaLookup = 'done';
    if (asset.dramaKey && db) {
      db.collection('mediaAssets').where('dramaKey', '==', String(asset.dramaKey)).where('mediaType', '==', 'video')
        .where('status', '==', 'ready').where('visibility', '==', 'public').orderBy('episodeNumber', 'asc').limit(100)
        .get().then(function (snapshot) {
          var episodes = snapshot.docs.map(function (doc) { return doc.data(); }).filter(function (entry) {
            var href = safeUrl(entry.linkedPostUrl); if (!href) return false;
            try { return new URL(href).origin === window.location.origin; } catch (error) { return false; }
          }).sort(function (a,b) { return (Number(a.episodeNumber)||0)-(Number(b.episodeNumber)||0); });
          var index = episodes.findIndex(function (entry) { return safeUrl(entry.linkedPostUrl) === item.contentUrl; });
          if (index > 0) { previous.href = safeUrl(episodes[index-1].linkedPostUrl); previous.hidden = false; }
          if (index >= 0 && index < episodes.length-1) { next.href = safeUrl(episodes[index+1].linkedPostUrl); next.hidden = false; }
        }).catch(function (error) { console.warn('Dramora episode navigation unavailable:', error); });
    }
    video.addEventListener('error', function () { note.textContent = 'Playback error. Verify media URL, public access, CORS, supported video format and byte-range requests.'; });
    video.addEventListener('stalled', function () { note.textContent = 'Stream is taking longer than expected. Check your connection or retry playback.'; });
    video.addEventListener('playing', function () { note.textContent = 'Playing · ' + String(asset.storageProvider || 'media').toUpperCase(); });
    video.addEventListener('ended', function () {
      if (next.href && auto.checked) {
        try { window.sessionStorage.setItem('dramora-autoplay-pending', '1'); } catch (error) {}
        window.location.assign(next.href);
      }
    });
    try {
      if (window.sessionStorage.getItem('dramora-autoplay-pending') === '1') {
        window.sessionStorage.removeItem('dramora-autoplay-pending');
        video.addEventListener('loadedmetadata', function () {
          var attempt = video.play();
          if (attempt && typeof attempt.catch === 'function') attempt.catch(function () { note.textContent = 'Tap Play to continue. Your browser blocked automatic playback.'; });
        }, { once: true });
      }
    } catch (error) {}
    attachVideoTracking();
  }

  function insertFavoriteButton() {
    if (window.location.pathname.indexOf('/p/') === 0) return;
    var postBody = document.querySelector('.post-body');
    if (!postBody || document.querySelector('.favorite-action')) return;
    var item;
    try { item = currentContent(); } catch (error) { return; }
    var bar = document.createElement('div');
    bar.className = 'post-actions';
    var button = document.createElement('button');
    button.type = 'button';
    button.className = 'favorite-action';
    button.textContent = '＋ Add to My List';
    bar.appendChild(button);
    var share = document.createElement('button');
    share.type = 'button';
    share.className = 'share-post-action';
    share.textContent = '↗ Share drama';
    share.addEventListener('click', function () {
      var shareData = { title: item.title, text: 'Watch ' + item.title + ' free on Dramora', url: item.contentUrl };
      if (navigator.share) {
        navigator.share(shareData).catch(function (error) {
          if (error && error.name !== 'AbortError') notify('Could not open the share menu.');
        });
      } else if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(item.contentUrl).then(function () {
          notify('Drama link copied.');
        }).catch(function () { notify('Copy failed. You can copy the page URL from your browser.'); });
      } else {
        notify('Use your browser menu to copy or share this page.');
      }
    });
    bar.appendChild(share);
    postBody.parentNode.insertBefore(bar, postBody);
    function refresh() {
      if (!currentUser || !firebaseReady) {
        button.textContent = '＋ Add to My List';
        button.classList.remove('is-saved');
        return;
      }
      DramoraData.isFavorite(item.contentId).then(function (saved) {
        button.textContent = saved ? '♥ Saved to My List' : '＋ Add to My List';
        button.classList.toggle('is-saved', saved);
      }).catch(function () {});
    }
    button.addEventListener('click', function () {
      if (!currentUser) { openModal(); return; }
      button.disabled = true;
      var operation = button.classList.contains('is-saved')
        ? DramoraData.removeFavorite(item.contentId)
        : DramoraData.addFavorite(item);
      operation.then(function () {
        refresh();
        notify(button.classList.contains('is-saved') ? 'Removed from My List.' : 'Added to My List.');
      }).catch(function (error) { notify(error.message || 'Could not update My List.'); })
        .finally(function () { button.disabled = false; });
    });
    refresh();
    window.addEventListener('dramora:auth', refresh);
  }

  function createPageShell(title, subtitle) {
    var section = document.createElement('section');
    section.className = 'library-page';
    var head = document.createElement('div');
    head.className = 'library-page-head';
    var h1 = document.createElement('h1'); h1.textContent = title;
    var p = document.createElement('p'); p.textContent = subtitle;
    head.appendChild(h1); head.appendChild(p); section.appendChild(head);
    return section;
  }
  function renderEmpty(container, message) {
    var empty = document.createElement('div');
    empty.className = 'library-empty';
    empty.textContent = message;
    container.appendChild(empty);
  }
  function renderCards(container, items, allowRemove) {
    if (!items.length) { renderEmpty(container, 'Nothing here yet. Add dramas to your list or start watching.'); return; }
    var grid = document.createElement('div'); grid.className = 'library-grid';
    items.forEach(function (item) {
      var card = document.createElement('article'); card.className = 'library-card';
      var destination = safeUrl(item.contentUrl) || '#';
      var link = document.createElement('a'); link.className = 'library-card-link';
      link.href = destination;
      var image = safeUrl(item.posterUrl);
      if (image) {
        var img = document.createElement('img'); img.loading = 'lazy'; img.src = image;
        img.alt = String(item.title || 'Drama poster'); link.appendChild(img);
      } else {
        var placeholder = document.createElement('div'); placeholder.className = 'library-card-placeholder';
        placeholder.textContent = 'DRAMORA'; link.appendChild(placeholder);
      }
      card.appendChild(link);
      var copy = document.createElement('div'); copy.className = 'library-card-copy';
      var title = document.createElement('h3');
      var titleLink = document.createElement('a'); titleLink.href = destination;
      titleLink.textContent = String(item.title || 'Untitled drama');
      title.appendChild(titleLink); copy.appendChild(title);
      if (allowRemove) {
        var remove = document.createElement('button'); remove.type = 'button';
        remove.className = 'library-remove'; remove.textContent = 'Remove from My List';
        remove.addEventListener('click', function () {
          remove.disabled = true;
          DramoraData.removeFavorite(item.contentId).then(function () {
            card.remove();
            if (!grid.children.length) renderEmpty(container, 'Your list is empty. Explore dramas and save your favorites.');
            notify('Removed from My List.');
          }).catch(function (error) {
            remove.disabled = false; notify(error.message || 'Could not remove this drama.');
          });
        });
        copy.appendChild(remove);
      }
      card.appendChild(copy); grid.appendChild(card);
    });
    container.appendChild(grid);
  }
  function renderSignInPrompt(container) {
    var empty = document.createElement('div'); empty.className = 'library-empty';
    var message = document.createElement('p'); message.textContent = 'Sign in to access your personal Dramora library.';
    var button = document.createElement('button'); button.type = 'button'; button.className = 'library-primary';
    button.textContent = 'Sign in';
    button.addEventListener('click', openModal);
    empty.appendChild(message); empty.appendChild(button); container.appendChild(empty);
  }
  function fetchBloggerCatalogPage(startIndex) {
    var start = Math.max(1, Number(startIndex) || 1);
    if (bloggerFeedCache[start]) return bloggerFeedCache[start];
    var request = fetch('/feeds/posts/default?alt=json&max-results=50&start-index=' + start, {
      method: 'GET', credentials: 'same-origin', headers: { Accept: 'application/json' }
    }).then(function (response) {
      if (!response.ok) throw new Error('Blogger returned HTTP ' + response.status + '.');
      return response.json();
    }).then(function (payload) {
      var entries = payload && payload.feed && Array.isArray(payload.feed.entry) ? payload.feed.entry : [];
      var items = entries.map(function (entry) {
        var title = String(entry.title && entry.title.$t || 'Untitled drama').trim().slice(0, 160);
        var links = Array.isArray(entry.link) ? entry.link : [];
        var alternate = links.find(function (link) { return link.rel === 'alternate' && link.type === 'text/html'; }) ||
          links.find(function (link) { return link.rel === 'alternate'; });
        var permalink = safeUrl(alternate && alternate.href);
        if (!permalink) return null;
        try { if (new URL(permalink).origin !== window.location.origin) return null; } catch (error) { return null; }
        var html = String((entry.summary && entry.summary.$t) || (entry.content && entry.content.$t) || '');
        var parsed = new DOMParser().parseFromString(html, 'text/html');
        var summary = String(parsed.body.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 210);
        var image = entry.media$thumbnail && entry.media$thumbnail.url;
        if (!image) {
          var firstImage = parsed.querySelector('img[src]');
          image = firstImage ? firstImage.getAttribute('src') : '';
        }
        var categories = Array.isArray(entry.category) ? entry.category : [];
        var labels = categories.map(function (category) {
          return String(category && category.term || '').trim().slice(0, 40);
        }).filter(function (label, index, list) { return label && list.indexOf(label) === index; }).slice(0, 8);
        return {
          title: title || 'Untitled drama', contentUrl: permalink,
          posterUrl: safeUrl(image) || '', summary: summary,
          labels: labels,
          published: String(entry.published && entry.published.$t || '')
        };
      }).filter(Boolean);
      return { items: items, received: entries.length };
    }).catch(function (error) {
      delete bloggerFeedCache[start];
      throw error;
    });
    bloggerFeedCache[start] = request;
    return request;
  }


  function seriesDisplayName(key) {
    return String(key || '').split('-').map(function (part) {
      return part ? part.charAt(0).toUpperCase() + part.slice(1) : '';
    }).join(' ');
  }

  function fetchPublicSeriesAssets(dramaKey) {
    if (!firebaseReady || !db) return Promise.reject(new Error('Firebase is not configured. Set the Firebase Web App values first.'));
    var query = db.collection('mediaAssets')
      .where('dramaKey', '==', dramaKey)
      .where('mediaType', '==', 'video')
      .where('status', '==', 'ready')
      .where('visibility', '==', 'public')
      .orderBy('episodeNumber', 'asc')
      .limit(100);
    return query.get().then(function (snapshot) {
      return snapshot.docs.map(function (doc) {
        return Object.assign({ id: doc.id }, doc.data());
      }).filter(function (asset) {
        if (!asset.linkedPostUrl || !safeUrl(asset.linkedPostUrl)) return false;
        try { return new URL(asset.linkedPostUrl).origin === window.location.origin; }
        catch (error) { return false; }
      });
    });
  }

  function renderSeriesCatalog(container) {
    if (!firebaseReady || !db) {
      renderEmpty(container, 'Series are temporarily unavailable until Firebase is configured.');
      return;
    }
    var section = document.createElement('section'); section.className = 'series-section';
    var heading = document.createElement('h2'); heading.textContent = 'Complete series';
    section.appendChild(heading);
    var grid = document.createElement('div'); grid.className = 'series-grid';
    section.appendChild(grid); container.appendChild(section);
    db.collection('mediaAssets')
      .where('dramaKey', '>', '')
      .where('mediaType', '==', 'video')
      .where('status', '==', 'ready')
      .where('visibility', '==', 'public')
      .orderBy('dramaKey', 'asc')
      .orderBy('episodeNumber', 'asc')
      .limit(200)
      .get()
      .then(function (snapshot) {
        var grouped = Object.create(null);
        snapshot.forEach(function (doc) {
          var asset = doc.data();
          var key = String(asset.dramaKey || '');
          if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(key)) return;
          if (!asset.linkedPostUrl || !safeUrl(asset.linkedPostUrl)) return;
          if (!grouped[key]) grouped[key] = { key: key, count: 0, title: seriesDisplayName(key) };
          grouped[key].count += 1;
          if (asset.seriesTitle && String(asset.seriesTitle).trim()) grouped[key].title = String(asset.seriesTitle).trim().slice(0, 100);
        });
        var keys = Object.keys(grouped);
        if (!keys.length) {
          var empty = document.createElement('p'); empty.className = 'discover-count';
          empty.textContent = 'No complete series have been published yet. Link episode videos to a drama key in Admin → Media Manager.';
          grid.appendChild(empty); return;
        }
        keys.sort(function (a, b) { return grouped[a].title.localeCompare(grouped[b].title); });
        keys.forEach(function (key) {
          var item = grouped[key];
          var link = document.createElement('a'); link.className = 'series-card';
          link.href = '/p/drama.html?key=' + encodeURIComponent(item.key);
          var title = document.createElement('strong'); title.textContent = item.title;
          var meta = document.createElement('span'); meta.textContent = item.count + (item.count === 1 ? ' episode' : ' episodes') + ' · Free to watch';
          link.appendChild(title); link.appendChild(meta); grid.appendChild(link);
        });
      })
      .catch(function (error) {
        var message = document.createElement('p'); message.className = 'discover-count';
        message.textContent = 'Series could not load: ' + (error.message || 'Check the Firestore index and public media rules.');
        grid.appendChild(message);
      });
  }

  function renderDramaSeriesPage() {
    var main = document.querySelector('.main-posts');
    if (!main || window.location.pathname.indexOf('/p/drama.html') !== 0) return;
    var key = String(new URLSearchParams(window.location.search).get('key') || '').trim().toLowerCase();
    var page = createPageShell('Drama series', 'Watch every published episode in order. All Dramora episodes are free.');
    main.replaceChildren(page);
    var back = document.createElement('a'); back.className = 'series-back'; back.href = '/p/discover.html';
    back.textContent = '← Back to Discover'; page.appendChild(back);
    if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(key)) {
      renderEmpty(page, 'This series link is invalid. Open a series from Discover.');
      return;
    }
    var title = document.createElement('h2'); title.textContent = seriesDisplayName(key);
    title.style.cssText = 'margin:0 0 8px;color:#fff;font-size:25px;';
    page.appendChild(title);
    var subtitle = document.createElement('p'); subtitle.className = 'discover-count';
    subtitle.textContent = 'Loading episodes…'; page.appendChild(subtitle);
    var list = document.createElement('div'); list.className = 'series-episode-list'; page.appendChild(list);
    fetchPublicSeriesAssets(key).then(function (assets) {
      if (assets[0] && assets[0].seriesTitle) title.textContent = String(assets[0].seriesTitle).slice(0, 100);
      subtitle.textContent = assets.length + (assets.length === 1 ? ' episode' : ' episodes') + ' · Free to watch';
      list.replaceChildren();
      if (!assets.length) {
        renderEmpty(list, 'No public episodes are linked to this series yet.');
        return;
      }
      assets.sort(function (a, b) {
        var an = Number(a.episodeNumber) || 0, bn = Number(b.episodeNumber) || 0;
        return an - bn || String(a.episodeTitle || a.title || '').localeCompare(String(b.episodeTitle || b.title || ''));
      });
      assets.forEach(function (asset, index) {
        var link = document.createElement('a'); link.className = 'series-episode';
        link.href = asset.linkedPostUrl;
        var copy = document.createElement('span'); copy.className = 'series-episode-copy';
        var name = document.createElement('strong');
        name.textContent = String(asset.episodeTitle || asset.title || ('Episode ' + (index + 1))).slice(0, 160);
        var detail = document.createElement('span');
        detail.textContent = asset.sizeBytes ? (asset.storageProvider === 'b2' ? 'Backblaze stream' : 'Blogger stream') + ' · ' + (Number(asset.sizeBytes) / 1048576).toFixed(1) + ' MB' : 'Free episode';
        copy.appendChild(name); copy.appendChild(detail);
        var number = document.createElement('span'); number.className = 'series-episode-number';
        number.textContent = 'EP ' + (Number(asset.episodeNumber) || index + 1);
        link.appendChild(copy); link.appendChild(number); list.appendChild(link);
      });
    }).catch(function (error) {
      subtitle.textContent = 'Could not load episodes.';
      renderEmpty(list, error.message || 'Check Firestore rules and indexes.');
    });
  }

  function renderDiscover() {
    var main = document.querySelector('.main-posts');
    if (!main || window.location.pathname.indexOf('/p/discover.html') !== 0) return;
    var page = createPageShell('Discover dramas', 'Browse public stories and complete free series published on Dramora.');
    main.replaceChildren(page);
    var tools = document.createElement('div'); tools.className = 'discover-tools';
    var search = document.createElement('input'); search.type = 'search'; search.className = 'discover-search';
    search.placeholder = 'Search drama titles, descriptions or labels…'; search.setAttribute('aria-label', 'Search dramas');
    var chips = document.createElement('div'); chips.className = 'discover-chip-row';
    var count = document.createElement('div'); count.className = 'discover-count'; count.setAttribute('aria-live', 'polite');
    tools.appendChild(search); tools.appendChild(chips); tools.appendChild(count); page.appendChild(tools);
    var seriesHost = document.createElement('div'); page.appendChild(seriesHost);
    renderSeriesCatalog(seriesHost);
    var results = document.createElement('div'); page.appendChild(results);
    var moreWrap = document.createElement('div'); moreWrap.className = 'discover-load-more'; page.appendChild(moreWrap);
    var items = [], nextStart = 1, hasMore = true, loading = false, activeLabel = 'All';

    function renderResults() {
      chips.replaceChildren();
      var labels = ['All'];
      items.forEach(function (item) { (item.labels || []).forEach(function (label) {
        if (labels.indexOf(label) < 0 && labels.length < 9) labels.push(label);
      }); });
      labels.forEach(function (label) {
        var chip = document.createElement('button'); chip.type = 'button';
        chip.className = 'discover-chip' + (activeLabel === label ? ' active' : '');
        chip.textContent = label;
        chip.addEventListener('click', function () { activeLabel = label; renderResults(); });
        chips.appendChild(chip);
      });
      var term = search.value.trim().toLowerCase();
      var filtered = items.filter(function (item) {
        var labelMatch = activeLabel === 'All' || (item.labels || []).indexOf(activeLabel) >= 0;
        var haystack = [item.title, item.summary, (item.labels || []).join(' ')].join(' ').toLowerCase();
        return labelMatch && (!term || haystack.indexOf(term) >= 0);
      });
      count.textContent = filtered.length + ' dramas shown · ' + items.length + ' posts loaded';
      results.replaceChildren();
      if (!filtered.length) {
        renderEmpty(results, items.length ? 'No dramas match this search. Try another title or label.' : 'No public Blogger posts were found yet. Publish a drama post to populate Discover.');
      } else {
        var grid = document.createElement('div'); grid.className = 'library-grid';
        filtered.forEach(function (item) {
          var card = document.createElement('article'); card.className = 'library-card';
          var link = document.createElement('a'); link.className = 'library-card-link'; link.href = item.contentUrl;
          if (item.posterUrl) {
            var image = document.createElement('img'); image.src = item.posterUrl; image.alt = item.title;
            image.loading = 'lazy'; image.decoding = 'async'; link.appendChild(image);
          } else {
            var placeholder = document.createElement('div'); placeholder.className = 'library-card-placeholder';
            placeholder.textContent = 'DRAMORA'; link.appendChild(placeholder);
          }
          card.appendChild(link);
          var copy = document.createElement('div'); copy.className = 'library-card-copy';
          var heading = document.createElement('h3'); var titleLink = document.createElement('a');
          titleLink.href = item.contentUrl; titleLink.textContent = item.title; heading.appendChild(titleLink); copy.appendChild(heading);
          if (item.summary) { var summary = document.createElement('p'); summary.className = 'discover-summary'; summary.textContent = item.summary; copy.appendChild(summary); }
          if (item.labels && item.labels.length) {
            var labelRow = document.createElement('div'); labelRow.className = 'discover-card-labels';
            item.labels.slice(0, 3).forEach(function (label) {
              var badge = document.createElement('span'); badge.className = 'mini-label'; badge.textContent = label; labelRow.appendChild(badge);
            });
            copy.appendChild(labelRow);
          }
          card.appendChild(copy); grid.appendChild(card);
        });
        results.appendChild(grid);
      }
      moreWrap.replaceChildren();
      if (hasMore) {
        var more = document.createElement('button'); more.type = 'button';
        more.textContent = loading ? 'Loading…' : 'Load more dramas'; more.disabled = loading;
        more.addEventListener('click', loadNextPage); moreWrap.appendChild(more);
      }
    }
    function loadNextPage() {
      if (loading || !hasMore) return;
      loading = true; renderResults();
      fetchBloggerCatalogPage(nextStart).then(function (result) {
        items = items.concat(result.items);
        nextStart += result.received;
        hasMore = result.received === 50;
        loading = false; renderResults();
      }).catch(function (error) {
        loading = false; hasMore = false;
        renderResults();
        var message = document.createElement('p'); message.className = 'admin-help';
        message.textContent = 'Could not load the public Blogger feed: ' + (error.message || 'Unknown feed error.') + ' Check that the blog and posts are public.';
        results.appendChild(message);
      });
    }
    search.addEventListener('input', renderResults);
    renderEmpty(results, 'Loading public drama posts…');
    loadNextPage();
  }

  function renderMyList() {
