  }

  // DRAMORA V4 community: one public room and private conversations with exactly two members.
  var profileSyncPromise = Promise.resolve();
  var communityState = {
    root: null, activeTab: 'public',
    public: { unsub: null, messages: {}, cursor: null, reply: null, blocked: new Set(), elements: null },
    private: { unsubList: null, unsubMessages: null, unsubConversation: null, messages: {}, cursor: null,
      selectedId: null, selectedData: null, peer: null, reply: null, elements: null, profileCache: {}, listDocs: [] }
  };
  function communityError(error) {
    var code = error && error.code ? error.code : '';
    if (code === 'permission-denied') return 'Access was denied. Check the published Firestore rules, account status, and block settings.';
    if (code === 'failed-precondition') return 'A Firestore index is required. Deploy the index file included with this release.';
    if (code === 'unavailable' || code === 'deadline-exceeded') return 'Connection problem. Please try again.';
    if (error && error.message && !code) return error.message;
    return 'The community action could not be completed. Please try again.';
  }
  function disposeCommunity() {
    ['unsub'].forEach(function (key) {
      if (communityState.public[key]) communityState.public[key]();
      communityState.public[key] = null;
    });
    ['unsubList', 'unsubMessages', 'unsubConversation'].forEach(function (key) {
      if (communityState.private[key]) communityState.private[key]();
      communityState.private[key] = null;
    });
    communityState.public.messages = {};
    communityState.public.cursor = null;
    communityState.public.reply = null;
    communityState.public.elements = null;
    communityState.private.messages = {};
    communityState.private.cursor = null;
    communityState.private.listDocs = [];
    communityState.private.selectedId = null;
    communityState.private.selectedData = null;
    communityState.private.peer = null;
    communityState.private.reply = null;
    communityState.private.elements = null;
    communityState.root = null;
  }
  function createButton(label, className, handler) {
    var button = document.createElement('button');
    button.type = 'button'; button.className = className || ''; button.textContent = label;
    if (handler) button.addEventListener('click', handler);
    return button;
  }
  function formatCommunityTime(value) {
    try {
      var date = value && typeof value.toDate === 'function' ? value.toDate() : new Date(value);
      if (!date || isNaN(date.getTime())) return 'just now';
      return new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(date);
    } catch (error) { return 'just now'; }
  }
  function appendSafeMessageText(target, value) {
    var text = String(value || '');
    var pattern = /https?:\/\/[^\s<>"']+/gi;
    var cursor = 0, match;
    while ((match = pattern.exec(text))) {
      var raw = match[0], clean = raw;
      while (/[.,!?;:)\]}]$/.test(clean)) clean = clean.slice(0, -1);
      if (match.index > cursor) target.appendChild(document.createTextNode(text.slice(cursor, match.index)));
      var href = safeUrl(clean);
      if (href) {
        var anchor = document.createElement('a');
        anchor.href = href; anchor.target = '_blank'; anchor.rel = 'noopener noreferrer';
        anchor.textContent = clean; target.appendChild(anchor);
      } else {
        target.appendChild(document.createTextNode(clean));
      }
      if (raw.length > clean.length) target.appendChild(document.createTextNode(raw.slice(clean.length)));
      cursor = match.index + raw.length;
    }
    if (cursor < text.length) target.appendChild(document.createTextNode(text.slice(cursor)));
  }
  function messageCollection(scope, conversationId) {
    if (scope === 'public') return db.collection('communityRooms').doc('public').collection('messages');
    return db.collection('conversations').doc(conversationId).collection('messages');
  }
  function messageReference(scope, conversationId, messageId) {
    return messageCollection(scope, conversationId).doc(messageId);
  }
  function setCommunityReply(scope, message) {
    var state = scope === 'public' ? communityState.public : communityState.private;
    state.reply = { id: message.id, text: String(message.text || '').slice(0, 150) };
    var elements = state.elements;
    if (elements && elements.replyBar) {
      elements.replyBar.hidden = false;
      elements.replyText.textContent = 'Replying to ' + (message.senderName || 'member') + ': ' + state.reply.text;
    }
    if (elements && elements.input) elements.input.focus();
  }
  function clearCommunityReply(scope) {
    var state = scope === 'public' ? communityState.public : communityState.private;
    state.reply = null;
    if (state.elements && state.elements.replyBar) state.elements.replyBar.hidden = true;
  }
  function toggleCommunityReaction(scope, conversationId, messageId, emoji, code, button) {
    var user = currentUser;
    if (!user) { openModal(); return; }
    var ref = messageReference(scope, conversationId, messageId).collection('reactions').doc(user.uid).collection('emojis').doc(code);
    button.disabled = true;
    ref.get().then(function (snapshot) {
      if (snapshot.exists) return ref.delete().then(function () { button.classList.remove('is-active'); });
      return ref.set({ userId: user.uid, emoji: emoji, createdAt: firebase.firestore.FieldValue.serverTimestamp() })
        .then(function () { button.classList.add('is-active'); });
    }).catch(function (error) { notify(communityError(error)); }).finally(function () { button.disabled = false; });
  }
  function reportCommunityMessage(scope, conversationId, message) {
    if (!currentUser || message.senderId === currentUser.uid) return;
    var reason = window.prompt('Why are you reporting this message? The selected message excerpt (up to 500 characters) will be shared with Dramora moderators.');
    if (!reason || !reason.trim()) return;
    var payload = {
      reporterUid: currentUser.uid,
      targetUid: String(message.senderId || ''),
      targetDisplayName: String(message.senderName || 'Dramora member').slice(0, 60),
      messageId: String(message.id || ''),
      scope: scope,
      conversationId: scope === 'private' ? String(conversationId || '') : '',
      reason: reason.trim().slice(0, 500),
      // The reporter explicitly submits this bounded excerpt for moderator review.
      messageExcerpt: String(message.text || '').slice(0, 500),
      status: 'open',
      createdAt: firebase.firestore.FieldValue.serverTimestamp()
    };
    db.collection('reports').add(payload).then(function () { notify('Report submitted for review.'); })
      .catch(function (error) { notify(communityError(error)); });
  }
  function blockCommunityUser(targetUid) {
    if (!currentUser || !targetUid || targetUid === currentUser.uid) return Promise.resolve();
    if (!window.confirm('Block this user? Their messages will be hidden from your community view.')) return Promise.resolve();
    var ref = db.collection('userBlocks').doc(currentUser.uid).collection('blockedUsers').doc(targetUid);
    return ref.get().then(function (existing) {
      if (existing.exists) { notify('This user is already blocked.'); return null; }
      return ref.set({ blockedUid: targetUid, createdAt: firebase.firestore.FieldValue.serverTimestamp() });
    }).then(function (result) {
      if (!result) return;
      communityState.public.blocked.add(targetUid);
      notify('User blocked. Their messages are now hidden from your view.');
      if (communityState.public.elements) renderPublicMessages();
      if (communityState.private.selectedData && communityState.private.selectedData.members.indexOf(targetUid) !== -1) {
        if (communityState.private.elements && communityState.private.elements.messages) {
          renderCommunityMessages(communityState.private.elements.messages, communityState.private.messages, 'private', communityState.private.selectedId);
        }
      }
      renderBlockedUsers();
      if (communityState.private.listDocs) renderConversationList(communityState.private.listDocs);
      return Promise.resolve();
    }).catch(function (error) { notify(communityError(error)); });
  }
  function createCommunityMessageNode(message, scope, conversationId) {
    var card = document.createElement('article'); card.className = 'community-message';
    var head = document.createElement('div'); head.className = 'community-message-head';
    var name = document.createElement('span'); name.className = 'community-message-name';
    name.textContent = message.senderName || 'Dramora member';
    var time = document.createElement('time'); time.className = 'community-message-time';
    time.textContent = formatCommunityTime(message.createdAt);
    head.appendChild(name); head.appendChild(time); card.appendChild(head);
    if (message.replyToText) {
      var quote = document.createElement('div'); quote.className = 'community-reply-quote';
      quote.textContent = 'Reply: ' + String(message.replyToText).slice(0, 150); card.appendChild(quote);
    }
    var body = document.createElement('div'); body.className = 'community-message-body';
    appendSafeMessageText(body, message.text); card.appendChild(body);
    var actions = document.createElement('div'); actions.className = 'community-message-actions';
    actions.appendChild(createButton('↩ Reply', 'community-message-action', function () { setCommunityReply(scope, message); }));
    [
      { emoji: '👍', code: 'like' },
      { emoji: '❤️', code: 'love' },
      { emoji: '😂', code: 'laugh' }
    ].forEach(function (choice) {
      var reaction = createButton(choice.emoji, 'community-message-action', function () {
        toggleCommunityReaction(scope, conversationId, message.id, choice.emoji, choice.code, reaction);
      });
      reaction.setAttribute('aria-label', 'React with ' + choice.emoji);
      actions.appendChild(reaction);
    });
    if (currentUser && message.senderId !== currentUser.uid) {
      actions.appendChild(createButton('Report', 'community-message-action', function () {
        reportCommunityMessage(scope, conversationId, message);
      }));
      actions.appendChild(createButton('Block', 'community-message-action', function () {
        blockCommunityUser(message.senderId);
      }));
    }
    card.appendChild(actions);
    return card;
  }
  function renderCommunityMessages(container, map, scope, conversationId) {
    if (!container) return;
    container.replaceChildren();
    var blocked = communityState.public.blocked;
    var items = Object.keys(map).map(function (id) { return Object.assign({ id: id }, map[id]); })
      .filter(function (item) { return !blocked.has(item.senderId); })
      .sort(function (a, b) {
        var at = a.createdAt && a.createdAt.toMillis ? a.createdAt.toMillis() : 0;
        var bt = b.createdAt && b.createdAt.toMillis ? b.createdAt.toMillis() : 0;
        return at - bt;
      });
    if (!items.length) { renderEmpty(container, 'No messages yet. Start the conversation.'); return; }
    items.forEach(function (message) { container.appendChild(createCommunityMessageNode(message, scope, conversationId)); });
    container.scrollTop = container.scrollHeight;
  }
  function renderPublicMessages() {
    var elements = communityState.public.elements;
    if (elements) renderCommunityMessages(elements.messages, communityState.public.messages, 'public', '');
  }
  function loadBlockedUsers() {
    if (!currentUser) return Promise.resolve();
    return db.collection('userBlocks').doc(currentUser.uid).collection('blockedUsers').get().then(function (snapshot) {
      communityState.public.blocked = new Set(snapshot.docs.map(function (doc) { return doc.id; }));
    });
  }
  function loadPublicMessages() {
    var state = communityState.public;
    if (state.unsub || !state.elements) return;
    var query = db.collection('communityRooms').doc('public').collection('messages')
      .orderBy('createdAt', 'desc').limit(30);
    state.unsub = query.onSnapshot(function (snapshot) {
      snapshot.docs.forEach(function (doc) { state.messages[doc.id] = doc.data(); });
      if (!state.cursor && snapshot.docs.length) state.cursor = snapshot.docs[snapshot.docs.length - 1];
      renderPublicMessages();
    }, function (error) {
      state.elements.messages.replaceChildren();
      var box = document.createElement('div'); box.className = 'community-error'; box.textContent = communityError(error);
      state.elements.messages.appendChild(box);
    });
  }
  function loadOlderPublicMessages() {
    var state = communityState.public;
    if (!state.cursor || !state.elements) return;
    state.elements.older.disabled = true;
    db.collection('communityRooms').doc('public').collection('messages').orderBy('createdAt', 'desc')
      .startAfter(state.cursor).limit(30).get().then(function (snapshot) {
        snapshot.docs.forEach(function (doc) { state.messages[doc.id] = doc.data(); });
        if (snapshot.docs.length) state.cursor = snapshot.docs[snapshot.docs.length - 1];
        else state.elements.older.hidden = true;
        renderPublicMessages();
      }).catch(function (error) { notify(communityError(error)); })
      .finally(function () { state.elements.older.disabled = false; });
  }
  function sendCommunityMessage(scope) {
    var state = scope === 'public' ? communityState.public : communityState.private;
    var elements = state.elements;
    if (!currentUser || !elements || !elements.input) return;
    var text = elements.input.value.trim();
    if (!text) return;
    if (text.length > 1000) { notify('Messages can contain up to 1,000 characters.'); return; }
    var conversationId = scope === 'private' ? state.selectedId : '';
    if (scope === 'private' && (!conversationId || !state.selectedData)) { notify('Choose a conversation first.'); return; }
    elements.send.disabled = true;
    profileSyncPromise.then(function () {
      var user = currentUser;
      if (!user) throw new Error('Please sign in again.');
      var batch = db.batch();
      var stamp = firebase.firestore.FieldValue.serverTimestamp();
      var rateRef = db.collection('communityRateLimits').doc(user.uid);
      batch.set(rateRef, { lastSentAt: stamp }, { merge: true });
      var messageRef = messageCollection(scope, conversationId).doc();
      var reply = state.reply || { id: '', text: '' };
      var payload = {
        senderId: user.uid,
        senderName: ((user.displayName || 'Dramora member').trim().slice(0, 60) || 'Dramora member'),
        senderPhotoURL: safeUrl(user.photoURL) || '',
        text: text,
        replyToMessageId: reply.id || '',
        replyToText: reply.text || '',
        createdAt: stamp
      };
      batch.set(messageRef, payload);
      if (scope === 'private') {
        var conversationRef = db.collection('conversations').doc(conversationId);
        return conversationRef.get().then(function (snapshot) {
          if (!snapshot.exists) throw new Error('This conversation no longer exists.');
          var data = snapshot.data();
          var recipient = data.members.filter(function (uid) { return uid !== user.uid; })[0];
          if (!recipient) throw new Error('Private conversations must contain exactly two members.');
          var unread = Object.assign({}, data.unreadFor || {});
          unread[user.uid] = 0;
          unread[recipient] = (Number(unread[recipient]) || 0) + 1;
          batch.update(conversationRef, {
            // Keep message text only in the private messages subcollection,
            // never in the conversation-list summary document.
            lastMessage: '', lastMessageId: messageRef.id, lastSenderId: user.uid,
            lastMessageAt: stamp, updatedAt: stamp, unreadFor: unread
          });
          return batch.commit();
        });
      }
      return batch.commit();
    }).then(function () {
      elements.input.value = '';
      clearCommunityReply(scope);
    }).catch(function (error) {
      notify(communityError(error));
    }).finally(function () { elements.send.disabled = false; });
  }
  function createComposer(scope, parent) {
    var composer = document.createElement('form'); composer.className = 'community-composer';
    var replyBar = document.createElement('div'); replyBar.className = 'community-replying'; replyBar.hidden = true;
    var replyText = document.createElement('span');
    var cancelReply = createButton('×', '', function () { clearCommunityReply(scope); });
    cancelReply.setAttribute('aria-label', 'Cancel reply');
