      snapshot.docs.forEach(function (blockDoc) {
        var uid = blockDoc.id;
        db.collection('publicProfiles').doc(uid).get().then(function (profileDoc) {
          if (!state.elements || state.elements.blocked !== elements.blocked) return;
          var profile = profileDoc.exists ? profileDoc.data() : { displayName: 'Dramora member' };
          var row = document.createElement('div'); row.className = 'community-person';
          var copy = document.createElement('span'); copy.className = 'community-person-copy';
          var name = document.createElement('strong'); name.textContent = profile.displayName || 'Dramora member';
          var sub = document.createElement('small'); sub.textContent = 'Blocked';
          copy.appendChild(name); copy.appendChild(sub);
          var unblock = createButton('Unblock', 'community-message-action', function () {
            unblock.disabled = true;
            blockDoc.ref.delete().then(function () {
              communityState.public.blocked.delete(uid);
              row.remove(); renderPublicMessages(); renderBlockedUsers();
              if (communityState.private.listDocs) renderConversationList(communityState.private.listDocs);
              notify('User unblocked.');
            }).catch(function (error) { unblock.disabled = false; notify(communityError(error)); });
          });
