  function loadConversationList() {
    var state = communityState.private;
    if (state.unsubList || !state.elements) return;
    var list = db.collection('conversations').where('members', 'array-contains', currentUser.uid)
      .orderBy('updatedAt', 'desc').limit(30);
    state.unsubList = list.onSnapshot(function (snapshot) {
      state.listDocs = snapshot.docs;
      renderConversationList(snapshot.docs);
    }, function (error) {
      state.elements.conversations.replaceChildren();
      var box = document.createElement('div'); box.className = 'community-error'; box.textContent = communityError(error);
      state.elements.conversations.appendChild(box);
    });
  }
  function renderConversationList(docs) {
    var state = communityState.private, elements = state.elements;
    if (!elements) return;
    elements.conversations.replaceChildren();
    if (!docs.length) { var empty = document.createElement('div'); empty.className = 'community-muted'; empty.textContent = 'Your private conversations will appear here.'; elements.conversations.appendChild(empty); return; }
    Promise.all(docs.map(function (doc) {
      var data = doc.data();
      var otherUid = data.members.filter(function (uid) { return uid !== currentUser.uid; })[0];
      if (!otherUid) return Promise.resolve(null);
      if (state.profileCache[otherUid]) return Promise.resolve({ doc: doc, data: data, profile: state.profileCache[otherUid], otherUid: otherUid });
      return db.collection('publicProfiles').doc(otherUid).get().then(function (profileDoc) {
        var profile = profileDoc.exists ? profileDoc.data() : { uid: otherUid, displayName: 'Dramora member', photoURL: '' };
        state.profileCache[otherUid] = profile;
        return { doc: doc, data: data, profile: profile, otherUid: otherUid };
      });
    })).then(function (rows) {
      if (!state.elements || state.elements.conversations !== elements.conversations) return;
      elements.conversations.replaceChildren();
      var visibleRows = rows.filter(function (row) {
        return !!row && !communityState.public.blocked.has(row.otherUid);
      });
      if (!visibleRows.length) {
        var empty = document.createElement('div'); empty.className = 'community-muted';
        empty.textContent = 'No private conversations to show. Blocked members are hidden here.';
        elements.conversations.appendChild(empty);
        return;
      }
      visibleRows.forEach(function (row) {
        var button = createButton('', 'community-conversation' + (state.selectedId === row.doc.id ? ' active' : ''), function () {
          openPrivateConversation(row.doc.id, row.profile);
        });
        button.setAttribute('data-conversation-id', row.doc.id);
        var avatar = document.createElement('span'); avatar.className = 'community-avatar';
        var photo = safeUrl(row.profile.photoURL);
        if (photo) { var img = document.createElement('img'); img.src = photo; img.alt = ''; avatar.appendChild(img); }
        else avatar.textContent = String(row.profile.displayName || 'D').charAt(0).toUpperCase();
        var copy = document.createElement('span'); copy.className = 'community-conversation-copy';
        var name = document.createElement('strong'); name.textContent = row.profile.displayName || 'Dramora member';
        var preview = document.createElement('small'); preview.textContent = 'Tap to open private messages';
        copy.appendChild(name); copy.appendChild(preview); button.appendChild(avatar); button.appendChild(copy);
        var unread = Number((row.data.unreadFor || {})[currentUser.uid]) || 0;
        if (unread > 0) { var count = document.createElement('span'); count.className = 'community-unread'; count.textContent = unread > 9 ? '9+' : String(unread); button.appendChild(count); }
        elements.conversations.appendChild(button);
      });
    }).catch(function (error) { notify(communityError(error)); });
  }
  function conversationDocumentId(uidA, uidB) {
    return [String(uidA), String(uidB)].sort().join('__');
  }
  function startPrivateConversation(profile) {
    if (!currentUser || !profile || !profile.uid || profile.uid === currentUser.uid) return;
    var ownBlock = db.collection('userBlocks').doc(currentUser.uid).collection('blockedUsers').doc(profile.uid);
    ownBlock.get().then(function (blockDoc) {
      if (blockDoc.exists) throw new Error('You have blocked this member. Unblock them before starting a conversation.');
      var members = [currentUser.uid, profile.uid].sort();
      var id = conversationDocumentId(members[0], members[1]);
      var ref = db.collection('conversations').doc(id);
      return db.runTransaction(function (transaction) {
        return transaction.get(ref).then(function (snapshot) {
          if (!snapshot.exists) {
            var unread = {}; unread[members[0]] = 0; unread[members[1]] = 0;
            var stamp = firebase.firestore.FieldValue.serverTimestamp();
            transaction.set(ref, {
              members: members, createdAt: stamp, updatedAt: stamp, lastMessageAt: stamp,
              lastMessage: '', lastMessageId: '', lastSenderId: '', unreadFor: unread
            });
          }
        });
      }).then(function () { stateProfileCache(profile); return openPrivateConversation(id, profile); });
    }).catch(function (error) { notify(communityError(error)); });
  }
  function stateProfileCache(profile) {
    if (profile && profile.uid) communityState.private.profileCache[profile.uid] = profile;
  }
  function openPrivateConversation(conversationId, peerProfile) {
    var state = communityState.private, elements = state.elements;
    if (!elements) return Promise.resolve();
    if (state.unsubMessages) state.unsubMessages();
    if (state.unsubConversation) state.unsubConversation();
    state.unsubMessages = null; state.unsubConversation = null;
    state.selectedId = conversationId; state.peer = peerProfile || null;
    state.messages = {}; state.cursor = null; state.reply = null;
    var main = elements.main; main.replaceChildren();
    var head = document.createElement('div'); head.className = 'community-private-head';
    var title = document.createElement('strong'); title.textContent = peerProfile ? peerProfile.displayName : 'Private conversation';
    var actions = document.createElement('div');
    var block = createButton('Block', '', function () { if (state.peer) blockCommunityUser(state.peer.uid); });
    var report = createButton('Report', '', function () {
      if (!state.peer) return;
      var reason = window.prompt('Why are you reporting this conversation?');
      if (!reason || !reason.trim()) return;
      db.collection('reports').add({
        reporterUid: currentUser.uid,
        targetUid: state.peer.uid,
        targetDisplayName: String(state.peer.displayName || 'Dramora member').slice(0, 60),
        messageId: '',
        scope: 'private',
        conversationId: conversationId,
        reason: reason.trim().slice(0, 500),
        messageExcerpt: '',
        status: 'open',
        createdAt: firebase.firestore.FieldValue.serverTimestamp()
      })
        .then(function () { notify('Report submitted for review.'); }).catch(function (error) { notify(communityError(error)); });
    });
    actions.appendChild(report); actions.appendChild(block); head.appendChild(title); head.appendChild(actions); main.appendChild(head);
    var older = createButton('Load older messages', 'community-load-older', loadOlderPrivateMessages);
    main.appendChild(older);
    var messages = document.createElement('div'); messages.className = 'community-messages'; messages.setAttribute('role', 'log'); messages.setAttribute('aria-live', 'polite');
    main.appendChild(messages);
    var composer = createComposer('private', main);
    composer.messages = messages; composer.older = older;
    state.elements.messages = messages; state.elements.older = older;
    state.elements.input = composer.input; state.elements.send = composer.send;
    state.elements.replyBar = composer.replyBar; state.elements.replyText = composer.replyText;
    var ref = db.collection('conversations').doc(conversationId);
    state.unsubConversation = ref.onSnapshot(function (snapshot) {
      if (!snapshot.exists) { messages.replaceChildren(); renderEmpty(messages, 'This conversation is no longer available.'); return; }
      state.selectedData = snapshot.data();
      if (state.selectedData.members.indexOf(currentUser.uid) === -1) { messages.replaceChildren(); renderEmpty(messages, 'You do not have access to this conversation.'); return; }
      title.textContent = peerProfile ? peerProfile.displayName : 'Private conversation';
      markPrivateConversationRead();
    }, function (error) { notify(communityError(error)); });
    var query = ref.collection('messages').orderBy('createdAt', 'desc').limit(30);
    state.unsubMessages = query.onSnapshot(function (snapshot) {
      snapshot.docs.forEach(function (doc) { state.messages[doc.id] = doc.data(); });
      if (!state.cursor && snapshot.docs.length) state.cursor = snapshot.docs[snapshot.docs.length - 1];
      renderCommunityMessages(messages, state.messages, 'private', conversationId);
      markPrivateConversationRead();
    }, function (error) { messages.replaceChildren(); var box = document.createElement('div'); box.className = 'community-error'; box.textContent = communityError(error); messages.appendChild(box); });
    renderConversationListPlaceholderActive();
    return Promise.resolve();
  }
  function renderConversationListPlaceholderActive() {
    var list = communityState.private.elements && communityState.private.elements.conversations;
    if (list) list.querySelectorAll('.community-conversation').forEach(function (button) {
      button.classList.toggle('active', button.getAttribute('data-conversation-id') === communityState.private.selectedId);
    });
  }
  function markPrivateConversationRead() {
    var state = communityState.private;
    if (!state.selectedId || !state.selectedData || !currentUser) return;
    var unread = Object.assign({}, state.selectedData.unreadFor || {});
    if ((Number(unread[currentUser.uid]) || 0) <= 0) return;
    unread[currentUser.uid] = 0;
    db.collection('conversations').doc(state.selectedId).update({ unreadFor: unread }).catch(function (error) {
      console.warn('Dramora read receipt update failed:', error);
    });
  }
  function loadOlderPrivateMessages() {
    var state = communityState.private;
    if (!state.cursor || !state.selectedId || !state.elements || !state.elements.messages) return;
    state.elements.older.disabled = true;
    db.collection('conversations').doc(state.selectedId).collection('messages').orderBy('createdAt', 'desc')
      .startAfter(state.cursor).limit(30).get().then(function (snapshot) {
        snapshot.docs.forEach(function (doc) { state.messages[doc.id] = doc.data(); });
        if (snapshot.docs.length) state.cursor = snapshot.docs[snapshot.docs.length - 1];
        else state.elements.older.hidden = true;
        renderCommunityMessages(state.elements.messages, state.messages, 'private', state.selectedId);
      }).catch(function (error) { notify(communityError(error)); })
      .finally(function () { if (state.elements && state.elements.older) state.elements.older.disabled = false; });
  }


  // DRAMORA V5 — privileged admin console. All privileges are enforced by
  // Firebase custom claims and Firestore rules; hiding this page is not security.
  function adminActionButton(label, handler, danger) {
    var button = document.createElement('button');
    button.type = 'button';
    button.className = 'admin-action' + (danger ? ' danger' : '');
    button.textContent = label;
    button.addEventListener('click', handler);
    return button;
  }
  function adminDate(value) {
    if (!value) return 'Date unavailable';
    var date = value.toDate ? value.toDate() : new Date(value);
    return isNaN(date.getTime()) ? 'Date unavailable' : date.toLocaleString();
  }
  function setUserRestriction(uid, status, reason) {
    if (!isAdminUser || !currentUser || !uid || uid === currentUser.uid) {
      return Promise.reject(new Error('You cannot change this account restriction.'));
    }
    var ref = db.collection('userModeration').doc(uid);
    return ref.get().then(function (snapshot) {
      var stamp = firebase.firestore.FieldValue.serverTimestamp();
      var payload = {
        status: status,
        reason: String(reason || '').slice(0, 500),
        updatedBy: currentUser.uid,
        updatedAt: stamp
      };
      if (!snapshot.exists) payload.createdAt = stamp;
      return ref.set(payload, { merge: true });
    });
  }
  function updateReportStatus(reportId, status, note) {
    if (!isAdminUser || !currentUser) return Promise.reject(new Error('Admin access required.'));
    return db.collection('reports').doc(reportId).update({
      status: status,
      reviewedAt: firebase.firestore.FieldValue.serverTimestamp(),
      reviewedBy: currentUser.uid,
      moderationNote: String(note || '').slice(0, 500)
    });
  }
  function renderAdminReportList(container, docs) {
    container.replaceChildren();
    var visibleDocs = docs.filter(function (doc) {
      var status = doc.data().status || 'open';
      return status !== 'resolved' && status !== 'dismissed';
    });
    var count = document.getElementById('adminOpenCount');
    if (count) count.textContent = String(visibleDocs.length);
    if (!visibleDocs.length) {
      renderEmpty(container, 'No active reports. New reports will appear here.');
      return;
    }
    visibleDocs.forEach(function (doc) {
      var report = doc.data();
      var card = document.createElement('article'); card.className = 'admin-report';
      var head = document.createElement('div'); head.className = 'admin-report-head';
      var titleWrap = document.createElement('div');
      var title = document.createElement('strong');
      title.textContent = (report.scope === 'private' ? 'Private message report' : 'Public chat report') +
        ' · ' + String(report.targetDisplayName || report.targetUid || 'Unknown member').slice(0, 80);
      var meta = document.createElement('div'); meta.className = 'admin-report-meta';
      meta.textContent = 'Report: ' + doc.id + ' · Target UID: ' + String(report.targetUid || '').slice(0, 18) +
        ' · Reporter UID: ' + String(report.reporterUid || '').slice(0, 18) +
        ' · ' + adminDate(report.createdAt);
      titleWrap.appendChild(title); titleWrap.appendChild(meta);
      var status = document.createElement('span'); status.className = 'admin-status ' + String(report.status || 'open');
      status.textContent = report.status || 'open';
      head.appendChild(titleWrap); head.appendChild(status); card.appendChild(head);
      var reason = document.createElement('div'); reason.className = 'admin-report-excerpt';
      reason.textContent = 'Reason: ' + String(report.reason || 'No reason supplied').slice(0, 500) +
        '\n\nReported excerpt: ' + String(report.messageExcerpt || 'This is an older report; no message excerpt was saved.').slice(0, 500);
      card.appendChild(reason);
      var actions = document.createElement('div'); actions.className = 'admin-actions';
      var markReviewed = adminActionButton('Mark reviewed', function () {
        markReviewed.disabled = true;
        updateReportStatus(doc.id, 'reviewed', 'Reviewed by administrator')
          .then(function () { notify('Report marked as reviewed.'); })
          .catch(function (error) { notify(error.message || 'Could not update report.'); })
          .finally(function () { markReviewed.disabled = false; });
      });
      actions.appendChild(markReviewed);
      var resolve = adminActionButton('Resolve report', function () {
        var note = window.prompt('Resolution note (optional):', 'Action taken after review');
        if (note === null) return;
        resolve.disabled = true;
        updateReportStatus(doc.id, 'resolved', note)
          .then(function () { notify('Report resolved.'); })
          .catch(function (error) { notify(error.message || 'Could not resolve report.'); })
          .finally(function () { resolve.disabled = false; });
      });
      actions.appendChild(resolve);
      var dismiss = adminActionButton('Dismiss', function () {
        if (!window.confirm('Dismiss this report?')) return;
        dismiss.disabled = true;
        updateReportStatus(doc.id, 'dismissed', 'Dismissed after review')
          .then(function () { notify('Report dismissed.'); })
          .catch(function (error) { notify(error.message || 'Could not dismiss report.'); })
          .finally(function () { dismiss.disabled = false; });
      }, true);
      actions.appendChild(dismiss);
      if (report.scope === 'public' && report.messageId) {
