  function loadAdminMedia(container) {
    container.replaceChildren();
    db.collection('mediaAssets').orderBy('createdAt', 'desc').limit(30).get().then(function (snapshot) {
      if (!container.isConnected) return;
      if (snapshot.empty) { renderEmpty(container, 'No media metadata registered yet.'); return; }
      snapshot.docs.forEach(function (doc) {
        var item = doc.data();
        var row = document.createElement('div'); row.className = 'admin-media-row';
        var copy = document.createElement('div');
        var name = document.createElement('strong'); name.textContent = String(item.title || item.fileName || 'Untitled media');
        var detail = document.createElement('small');
        detail.textContent = String(item.storageProvider || '') + ' · ' + String(item.mediaType || '') +
          ' · ' + (Number(item.sizeBytes || 0) / 1048576).toFixed(1) + ' MB · ' + String(item.status || 'ready') +
          (item.linkedPostUrl ? ' · Linked: ' + String(item.dramaKey || 'Blogger post') + (item.episodeNumber ? ' · Ep ' + item.episodeNumber : '') : ' · Not linked to a post');
        var link = document.createElement('a'); link.className = 'admin-link'; link.href = safeUrl(item.mediaUrl) || '#';
        link.target = '_blank'; link.rel = 'noopener noreferrer'; link.textContent = 'Open media';
        copy.appendChild(name); copy.appendChild(detail); copy.appendChild(link);
        var copyUrl = adminActionButton('Copy URL', function () {
          var value = safeUrl(item.mediaUrl);
          if (!value) { notify('This media URL is invalid.'); return; }
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(value).then(function () { notify('Media URL copied.'); })
              .catch(function () { window.prompt('Copy this media URL:', value); });
          } else {
            window.prompt('Copy this media URL:', value);
          }
        });
        copy.appendChild(copyUrl);
        row.appendChild(copy);
        var linkPost = adminActionButton(item.linkedPostUrl ? 'Edit post link' : 'Link to post', function () {
          var postUrl = window.prompt('Paste the canonical HTTPS Blogger post URL on this Dramora blog:', item.linkedPostUrl || '');
          if (postUrl === null) return;
          var meta;
          if (!postUrl.trim()) {
            meta = normalizeMediaLinkMeta('', '', '', '');
          } else {
            var dramaKey = window.prompt('Drama key (example: hidden-love):', item.dramaKey || '');
            if (dramaKey === null) return;
            var episodeNumber = window.prompt('Episode number (leave blank for a non-numbered asset):', item.episodeNumber || '');
            if (episodeNumber === null) return;
            var episodeTitle = window.prompt('Episode title (optional):', item.episodeTitle || item.title || '');
            if (episodeTitle === null) return;
            var seriesTitle = window.prompt('Series display title (optional):', item.seriesTitle || seriesDisplayName(dramaKey));
            if (seriesTitle === null) return;
            try { meta = normalizeMediaLinkMeta(postUrl, dramaKey, episodeNumber, episodeTitle); }
            catch (error) { notify(error.message); return; }
          }
          linkPost.disabled = true;
          doc.ref.update(Object.assign({}, meta, { seriesTitle: String(seriesTitle || '').trim().slice(0, 100), updatedAt: firebase.firestore.FieldValue.serverTimestamp() }))
            .then(function () { notify(meta.linkedPostUrl ? 'Media linked to the Blogger post.' : 'Post link cleared.'); loadAdminMedia(container); })
            .catch(function (error) { notify(error.message || 'Could not update the post link.'); })
            .finally(function () { linkPost.disabled = false; });
        });
        row.appendChild(linkPost);
        var hide = adminActionButton(item.visibility === 'private' || item.status === 'hidden' ? 'Publish' : 'Hide', function () {
          var nextVisibility = item.visibility === 'private' || item.status === 'hidden' ? 'public' : 'private';
          var nextStatus = nextVisibility === 'public' ? 'ready' : 'hidden';
          hide.disabled = true;
          doc.ref.update({
            visibility: nextVisibility, status: nextStatus,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp()
          }).then(function () { notify('Media visibility updated.'); loadAdminMedia(container); })
            .catch(function (error) { notify(error.message || 'Could not update media.'); })
            .finally(function () { hide.disabled = false; });
        });
        row.appendChild(hide); container.appendChild(row);
      });
    }).catch(function (error) {
      renderEmpty(container, error.message || 'Could not load media. Check Firestore rules.');
    });
  }
