    [titleField,postUrlField,dramaKeyField,seriesTitleField,episodeNumberField,episodeTitleField,providerField,typeField,urlField,sizeField,fileField,fallbackWrap,help,linkHelp,submit,statusNode].forEach(function (node) { form.appendChild(node); });
    function refreshMediaForm() {
