      event.preventDefault();
      if (!isAdminUser || !currentUser) { notify('Administrator access required.'); return; }
      var titleValue = titleInput.value.trim().slice(0,160);
      if (!titleValue) { notify('Enter a media title.'); return; }
      submit.disabled = true; statusNode.textContent = 'Preparing media operation…';
