      try { linkMeta = normalizeMediaLinkMeta(postUrlInput.value, dramaKeyInput.value, episodeNumberInput.value, episodeTitleInput.value); }
      catch (error) { submit.disabled = false; statusNode.textContent = error.message; notify(error.message); return; }
