        }
        if (!/^video\/(mp4|webm|quicktime|x-matroska)$/i.test(file.type)) {
          submit.disabled = false; statusNode.textContent = 'Please correct the highlighted media details.'; notify('Use MP4, WebM, MOV or MKV video with a recognized MIME type.'); return;
        }
        if (file.size <= 100 * 1048576 && !fallbackInput.checked) {
          submit.disabled = false; statusNode.textContent = 'Please correct the highlighted media details.';
          notify('B2 is for videos above 100 MB. Tick the fallback option if Blogger upload failed.'); return;
        }
        if (!DRAMORA_MEDIA_API_URL || DRAMORA_MEDIA_API_URL.indexOf('REPLACE_') === 0) {
          submit.disabled = false; statusNode.textContent = 'Please correct the highlighted media details.'; notify('Deploy the Cloudflare Worker and set its URL in the Blogger XML first.'); return;
        }
