              episodeNumber: linkMeta.episodeNumber, episodeTitle: linkMeta.episodeTitle, seriesTitle: String(seriesTitleInput.value || '').trim().slice(0, 100),
              status: 'ready', visibility: 'public', createdBy: currentUser.uid,
              createdAt: firebase.firestore.FieldValue.serverTimestamp(),
              updatedAt: firebase.firestore.FieldValue.serverTimestamp()
            });
          });
        });
      }
      // Capture the public URL after the signed authorization is returned, so an
