  function renderHomeContinueWatching() {
    var section = document.getElementById('dramoraContinueSection');
    var grid = document.getElementById('dramoraContinueGrid');
    if (!section || !grid) return;
    if (!currentUser || !firebaseReady) {
      section.hidden = true;
      grid.replaceChildren();
      return;
    }
    section.hidden = false;
    var requestedUid = currentUser.uid;
    grid.replaceChildren();
    var loading = document.createElement('div');
    loading.className = 'empty-state';
    loading.textContent = 'Loading your watch history…';
    grid.appendChild(loading);
    DramoraData.listWatchHistory(8).then(function (result) {
      if (!document.getElementById('dramoraContinueGrid') || !currentUser || currentUser.uid !== requestedUid) return;
      grid.replaceChildren();
      var items = (result && result.items) || [];
      if (!items.length) {
        var empty = document.createElement('div');
        empty.className = 'empty-state';
        empty.textContent = 'Your watch history will appear here after you start watching a drama.';
        grid.appendChild(empty);
        return;
      }
      items.forEach(function (item) {
        var url = safeUrl(item.contentUrl);
        if (!url) return;
        var card = document.createElement('article');
        card.className = 'continue-card';
        var link = document.createElement('a');
        link.className = 'continue-card-link';
        link.href = url;
        var poster = document.createElement('div');
        poster.className = 'continue-poster';
        var imageUrl = safeUrl(item.posterUrl);
        if (imageUrl) {
          var image = document.createElement('img');
          image.src = imageUrl;
          image.alt = String(item.title || 'Drama poster');
          image.loading = 'lazy';
          image.decoding = 'async';
          poster.appendChild(image);
        } else {
          var fallback = document.createElement('div');
          fallback.className = 'continue-poster-fallback';
          fallback.textContent = 'DRAMORA';
          poster.appendChild(fallback);
        }
        link.appendChild(poster);
        var copy = document.createElement('div');
        copy.className = 'continue-copy';
        var title = document.createElement('strong');
        title.textContent = String(item.title || 'Untitled drama');
        var position = Math.max(0, Number(item.positionSeconds) || 0);
        var duration = Math.max(0, Number(item.durationSeconds) || 0);
        var detail = document.createElement('span');
        detail.textContent = duration > 0
          ? 'Continue · ' + Math.floor(position / 60) + ':' + String(Math.floor(position % 60)).padStart(2, '0')
          : 'Continue watching';
        copy.appendChild(title);
        copy.appendChild(detail);
        if (duration > 0) {
          var track = document.createElement('div');
          track.className = 'continue-progress';
          var fill = document.createElement('span');
          fill.style.width = Math.min(100, Math.max(0, position / duration * 100)) + '%';
          track.appendChild(fill);
          copy.appendChild(track);
        }
        link.appendChild(copy);
        card.appendChild(link);
        grid.appendChild(card);
      });
      if (!grid.children.length) {
        var invalid = document.createElement('div');
        invalid.className = 'empty-state';
        invalid.textContent = 'No playable watch-history links were found.';
        grid.appendChild(invalid);
      }
    }).catch(function (error) {
      if (!currentUser || currentUser.uid !== requestedUid) return;
      grid.replaceChildren();
      var failed = document.createElement('div');
      failed.className = 'empty-state';
      failed.textContent = error.message || 'Could not load your watch history.';
      grid.appendChild(failed);
    });
  }

  function renderAccountPages() {
    renderHomeContinueWatching();
    renderDramaSeriesPage();
    renderDiscover();
    renderMyList();
    renderProfile();
    renderCommunity();
    renderAdminPage();
  }

  function attachVideoTracking() {
    if (!currentUser || !firebaseReady || window.location.pathname.indexOf('/p/') === 0) return;
    var item; try { item = currentContent(); } catch (error) { return; }
    document.querySelectorAll('.post-body video').forEach(function (video) {
      if (video.dataset.dramoraTracking === 'true') return;
      video.dataset.dramoraTracking = 'true';
      var lastSave = 0, resumeStarted = false, saveInFlight = false;
      function resume() {
        if (resumeStarted || !currentUser) return; resumeStarted = true;
        DramoraData.getWatchProgress(item.contentId).then(function (progress) {
          if (!progress || progress.completed || video.currentTime > 1) return;
          var position = Number(progress.positionSeconds) || 0, duration = Number(video.duration) || 0;
          if (position > 5 && (!duration || duration-position > 8)) {
            try {
              video.currentTime = position;
              var hint = document.createElement('p'); hint.className = 'registered-player-note';
              hint.textContent = 'Resumed from ' + Math.floor(position/60) + ':' + String(Math.floor(position%60)).padStart(2,'0');
              if (video.parentNode) video.parentNode.insertBefore(hint, video.nextSibling);
            } catch (error) {}
          }
        }).catch(function () {});
      }
      function save(force) {
        if (!currentUser || !isFinite(video.currentTime) || saveInFlight) return;
        var now = Date.now(); if (!force && now-lastSave < 15000 && !video.paused && !video.ended) return;
        lastSave = now; saveInFlight = true;
        DramoraData.saveWatchProgress({
          contentId:item.contentId, contentUrl:item.contentUrl, title:item.title, posterUrl:item.posterUrl,
          positionSeconds:video.ended && isFinite(video.duration) ? video.duration : video.currentTime,
          durationSeconds:isFinite(video.duration) ? video.duration : 0, completed:!!video.ended
        }).catch(function (error) { console.warn('Dramora watch progress could not be saved:',error); })
          .finally(function () { saveInFlight = false; });
      }
      video.addEventListener('loadedmetadata',resume);
      video.addEventListener('timeupdate',function(){save(false);});
      video.addEventListener('pause',function(){save(true);});
      video.addEventListener('ended',function(){save(true);});
      window.addEventListener('pagehide',function(){save(true);});
      if (video.readyState >= 1) resume();
    });
  }

  function handleAuthChange(user) {
    currentUser = user || null;
    isAdminUser = false;
    adminClaimsReady = !currentUser;
    var adminNav = document.getElementById('adminNavLink');
    if (adminNav) adminNav.hidden = true;
    if (authOpenBtn) authOpenBtn.textContent = currentUser ? 'My Account' : 'Sign in';
    if (currentUser) {
      profileSyncPromise = syncProfile(currentUser).catch(function (error) {
        console.warn('Dramora profile sync failed:', error);
        if (modal.classList.contains('is-open')) showError('You are signed in, but your profile could not sync. Check the published Firestore rules.');
        throw error;
      });
      profileSyncPromise.catch(function () {});
      currentUser.getIdTokenResult(true).then(function (tokenResult) {
        isAdminUser = tokenResult.claims.admin === true;
        adminClaimsReady = true;
        if (adminNav) adminNav.hidden = !isAdminUser;
        renderAdminPage();
      }).catch(function (error) {
        console.warn('Dramora admin claim check failed:', error);
        adminClaimsReady = true;
        isAdminUser = false;
        renderAdminPage();
      });
    } else {
      profileSyncPromise = Promise.resolve();
      disposeCommunity();
      disposeAdminPage();
    }
    if (modal.classList.contains('is-open')) {
      if (currentUser) renderSignedIn(currentUser);
      else setMode('login');
    }
    window.dispatchEvent(new CustomEvent('dramora:auth', { detail: { user: currentUser } }));
    renderAccountPages();
    attachRegisteredMediaPlayer();
    attachVideoTracking();
    if (currentUser) insertFavoriteButton();
  }

  if (configReady) {
    try {
      if (!window.firebase.apps.length) window.firebase.initializeApp(firebaseConfig);
      auth = window.firebase.auth();
      db = window.firebase.firestore();
      firebaseReady = true;
      persistenceReady = auth.setPersistence(window.firebase.auth.Auth.Persistence.LOCAL)
        .catch(function (error) { console.warn('Dramora persistence setup:', error); });
      persistenceReady.then(function () {
        auth.onAuthStateChanged(handleAuthChange);
        auth.getRedirectResult().catch(function (error) {
          console.warn('Dramora Google redirect sign-in:', error);
        });
      });
    } catch (error) {
      console.error('Dramora Firebase initialization failed:', error);
      showError('Firebase could not initialize. Check the Web App configuration in the theme.');
    }
  } else {
    if (authOpenBtn) authOpenBtn.addEventListener('click', function () {
      showError('Firebase is not configured yet. Add your Firebase Web App values in the Blogger XML and complete the setup guide.');
    });
    renderAccountPages();
  }

  authForm.addEventListener('submit', function (event) {
    event.preventDefault();
    if (!firebaseReady) { showError('Firebase is not configured. Follow the setup guide first.'); return; }
    clearMessages();
    var email = el('authEmail').value.trim();
    var password = el('authPassword').value;
    var submit = el('authSubmitBtn');
    if (password.length < 8) { showError('Use a password with at least 8 characters.'); return; }
    submit.disabled = true;
    persistenceReady.then(function () {
      if (mode === 'signup') {
        var displayName = el('authDisplayName').value.trim().slice(0, 60) || 'Dramora member';
        if (password !== el('authConfirmPassword').value) throw new Error('The passwords do not match.');
        return auth.createUserWithEmailAndPassword(email, password).then(function (credential) {
          return credential.user.updateProfile({ displayName: displayName })
            .then(function () { return credential.user.sendEmailVerification(); })
            .then(function () { return credential.user.reload(); })
            .then(function () { return syncProfile(auth.currentUser || credential.user); })
            .then(function () { renderSignedIn(auth.currentUser || credential.user); showSuccess('Account created. Check your inbox for the verification email.'); });
        });
      }
      return auth.signInWithEmailAndPassword(email, password).then(function (credential) {
        return credential.user.reload().then(function () {
          return credential.user.getIdToken(true);
        }).then(function () {
          return syncProfile(auth.currentUser || credential.user);
        }).then(function () { renderSignedIn(auth.currentUser || credential.user); });
      });
    }).catch(function (error) {
      showError(error.message && !error.code ? error.message : friendlyError(error));
    }).finally(function () { submit.disabled = false; });
  });

  el('authGoogleBtn').addEventListener('click', function () {
    if (!firebaseReady) { showError('Firebase is not configured. Follow the setup guide first.'); return; }
    clearMessages();
    var provider = new firebase.auth.GoogleAuthProvider();
    provider.setCustomParameters({ prompt: 'select_account' });
    el('authGoogleBtn').disabled = true;
    persistenceReady.then(function () { return auth.signInWithPopup(provider); })
      .then(function (credential) { return syncProfile(credential.user); })
      .then(function () { if (auth.currentUser) renderSignedIn(auth.currentUser); })
      .catch(function (error) {
        if (error.code === 'auth/popup-blocked' || error.code === 'auth/operation-not-supported-in-this-environment') {
          auth.signInWithRedirect(provider).catch(function (redirectError) {
            showError(friendlyError(redirectError));
          });
          return;
        }
        showError(friendlyError(error));
      })
      .finally(function () { el('authGoogleBtn').disabled = false; });
  });
  el('authForgotBtn').addEventListener('click', function () {
    if (!firebaseReady) { showError('Firebase is not configured. Follow the setup guide first.'); return; }
    var email = el('authEmail').value.trim();
    if (!email) { showError('Enter your email address first.'); el('authEmail').focus(); return; }
    auth.sendPasswordResetEmail(email).then(function () {
      showSuccess('If an account exists for this email, a password reset message has been sent.');
    }).catch(function (error) {
      // Keep the same response for unknown addresses to avoid account enumeration.
      if (error && error.code === 'auth/user-not-found') {
        showSuccess('If an account exists for this email, a password reset message has been sent.');
      } else {
        showError(friendlyError(error));
      }
    });
  });
  el('authResendBtn').addEventListener('click', function () {
    if (!auth || !auth.currentUser) return;
    var button = el('authResendBtn');
    button.disabled = true;
    auth.currentUser.sendEmailVerification().then(function () {
      showSuccess('Verification email sent. Check your inbox and spam folder.');
    }).catch(function (error) { showError(friendlyError(error)); })
      .finally(function () { button.disabled = false; });
  });
  el('authCheckVerificationBtn').addEventListener('click', function () {
    if (!auth || !auth.currentUser) return;
    var button = el('authCheckVerificationBtn');
    button.disabled = true;
    auth.currentUser.reload().then(function () {
      currentUser = auth.currentUser;
      return currentUser.getIdToken(true);
    }).then(function () {
      // Wait for any initial auth-state profile sync to settle, then write
      // the refreshed user object so emailVerified cannot be overwritten
      // by an older in-flight profile payload.
      return profileSyncPromise.catch(function () { return null; });
    }).then(function () {
      return syncProfile(currentUser);
    }).then(function () {
      renderSignedIn(currentUser);
      if (currentUser.emailVerified) {
        showSuccess('Email verified successfully. Your Dramora profile is up to date.');
        window.dispatchEvent(new CustomEvent('dramora:auth', { detail: { user: currentUser } }));
      } else {
        showError('Verification is not confirmed yet. Open the latest email from Firebase, follow its link, then refresh this status again.');
      }
    }).catch(function (error) {
      showError(friendlyError(error));
    }).finally(function () { button.disabled = false; });
  });
  el('authLogoutBtn').addEventListener('click', function () {
    if (!auth) return;
    auth.signOut().then(function () { closeModal(); notify('You have signed out.'); })
      .catch(function (error) { showError(friendlyError(error)); });
  });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { insertFavoriteButton(); attachRegisteredMediaPlayer(); });
  } else {
    insertFavoriteButton();
    attachRegisteredMediaPlayer();
  }
}());

// Dramora V9: accessible featured drama carousel. Uses Blogger posts as its source.
(function initDramoraFeaturedCarousel() {
  var root = document.getElementById('dramoraFeatured');
  if (!root) return;
  var slides = Array.prototype.slice.call(root.querySelectorAll('.featured-slide'));
  var dotsHost = document.getElementById('dramoraFeaturedDots');
  var previous = document.getElementById('dramoraFeaturedPrev');
  var next = document.getElementById('dramoraFeaturedNext');
  if (!slides.length) return;
  var active = 0, timer = null, reducedMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if (slides.length < 2) {
    if (previous) previous.hidden = true;
    if (next) next.hidden = true;
    if (dotsHost) dotsHost.hidden = true;
  }
  function show(index) {
    active = (index + slides.length) % slides.length;
    slides.forEach(function (slide, i) {
      var selected = i === active;
      slide.classList.toggle('is-active', selected);
      slide.setAttribute('aria-hidden', selected ? 'false' : 'true');
    });
    if (dotsHost) Array.prototype.forEach.call(dotsHost.children, function (dot, i) {
      dot.setAttribute('aria-current', i === active ? 'true' : 'false');
      dot.setAttribute('tabindex', i === active ? '0' : '-1');
    });
  }
  function stop() { if (timer) { window.clearInterval(timer); timer = null; } }
  function start() {
    stop();
    if (slides.length > 1 && !reducedMotion && !document.hidden) timer = window.setInterval(function () { show(active + 1); }, 6500);
  }
  if (dotsHost && slides.length > 1) slides.forEach(function (_, i) {
    var dot = document.createElement('button');
    dot.type = 'button'; dot.className = 'featured-dot';
    dot.setAttribute('aria-label', 'Show featured drama ' + (i + 1));
    dot.addEventListener('click', function () { show(i); start(); });
    dotsHost.appendChild(dot);
  });
  if (previous) previous.addEventListener('click', function () { show(active - 1); start(); });
  if (next) next.addEventListener('click', function () { show(active + 1); start(); });
  // Mobile swipe support: horizontal gestures change slides without blocking vertical page scroll.
  var touchStart = null;
  root.addEventListener('touchstart', function (event) {
    if (!event.touches || event.touches.length !== 1) { touchStart = null; return; }
    if (event.target && event.target.closest && event.target.closest('a,button,input,textarea,select')) { touchStart = null; return; }
    touchStart = { x:event.touches[0].clientX, y:event.touches[0].clientY };
    stop();
  }, { passive:true });
  root.addEventListener('touchend', function (event) {
    if (!touchStart || !event.changedTouches || !event.changedTouches.length) { touchStart = null; start(); return; }
    var deltaX = event.changedTouches[0].clientX - touchStart.x;
    var deltaY = event.changedTouches[0].clientY - touchStart.y;
    if (Math.abs(deltaX) >= 48 && Math.abs(deltaX) > Math.abs(deltaY) * 1.2) show(active + (deltaX < 0 ? 1 : -1));
    touchStart = null;
    start();
  }, { passive:true });
  root.addEventListener('touchcancel', function () { touchStart = null; start(); }, { passive:true });
  root.addEventListener('mouseenter', stop);
  root.addEventListener('mouseleave', start);
  root.addEventListener('focusin', stop);
  root.addEventListener('focusout', function (event) { if (!root.contains(event.relatedTarget)) start(); });
  document.addEventListener('visibilitychange', function () { if (document.hidden) stop(); else start(); });
  show(0); start();
}());
// V9.3: public Blogger feed sections. Trending is an editorial Blogger label, not a fabricated popularity score.
(function initDramoraHomeFeeds() {
  var configs = [
    { id: 'dramoraTrendingGrid', url: '/feeds/posts/default/-/Trending?alt=json&max-results=8', empty: 'No dramas have been marked with the Trending label yet.' },
    { id: 'dramoraLatestGrid', url: '/feeds/posts/default?alt=json&max-results=8', empty: 'No recent posts are available yet.' }
  ];
  function field(entry, key) { return entry && entry[key] && entry[key].$t ? entry[key].$t : ''; }
  function entryUrl(entry) {
    var links = entry && entry.link || [];
    for (var i = 0; i < links.length; i++) if (links[i].rel === 'alternate') return safeUrl(links[i].href);
    return '';
  }
  function renderFeed(host, entries, emptyText) {
    host.replaceChildren();
    if (!entries.length) {
      var empty = document.createElement('div'); empty.className = 'empty-state';
      empty.textContent = emptyText; host.appendChild(empty); return;
    }
    entries.forEach(function (entry) {
      var url = entryUrl(entry); if (!url) return;
      var card = document.createElement('article'); card.className = 'drama-card';
      var link = document.createElement('a'); link.href = url;
      var poster = document.createElement('div'); poster.className = 'poster';
      var thumb = entry['media$thumbnail'] && entry['media$thumbnail'].url;
      if (!thumb) {
        var html = field(entry, 'content') || field(entry, 'summary');
        var match = html.match(/<img[^>]+src=["']([^"']+)["']/i);
        thumb = match ? match[1] : '';
      }
      var imageUrl = safeUrl(thumb);
      if (imageUrl) {
        var img = document.createElement('img'); img.src = imageUrl; img.alt = field(entry, 'title') || 'Drama poster';
        img.loading = 'lazy'; img.decoding = 'async'; poster.appendChild(img);
      } else {
        var placeholder = document.createElement('div'); placeholder.className = 'poster-placeholder';
        placeholder.textContent = 'DRAMORA'; poster.appendChild(placeholder);
      }
      var shade = document.createElement('div'); shade.className = 'poster-shade'; poster.appendChild(shade);
      link.appendChild(poster);
      var meta = document.createElement('div'); meta.className = 'drama-meta';
      var title = document.createElement('h3'); title.textContent = field(entry, 'title') || 'Untitled drama';
      var date = document.createElement('p'); date.textContent = field(entry, 'published');
      meta.appendChild(title); meta.appendChild(date); link.appendChild(meta);
      card.appendChild(link); host.appendChild(card);
    });
    if (!host.children.length) {
      var none = document.createElement('div'); none.className = 'empty-state';
      none.textContent = emptyText; host.appendChild(none);
    }
  }
  configs.forEach(function (config) {
    var host = document.getElementById(config.id); if (!host) return;
    fetch(config.url, { credentials: 'same-origin', headers: { 'Accept': 'application/json' } })
      .then(function (response) {
        if (!response.ok) throw new Error('Blogger feed request failed (' + response.status + ').');
        return response.json();
      })
      .then(function (data) {
        var entries = data && data.feed && data.feed.entry ? data.feed.entry : [];
        renderFeed(host, entries, config.empty);
      })
      .catch(function () {
        host.replaceChildren();
        var fallback = document.createElement('div'); fallback.className = 'empty-state';
        fallback.textContent = 'This section could not load. Please check the Blogger feed settings.';
        host.appendChild(fallback);
      });
  });
}());
